/// Shared component-token completion for CSSOM entry points. Source parsing
/// keeps ranges in the original bytes and does not rewrite the stylesheet.
pub fn complete_css_component_value(input:&str)->Result<Option<alloc::borrow::Cow<'_,str>>,CssError> {
    syntax::complete(input)
}

