#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum Overflow {
    #[default]
    Visible,
    Hidden,
    Scroll,
    Auto,
    Clip,
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ContainerType { #[default] Normal, InlineSize, Size }
impl ContainerType {
    pub const fn as_str(self) -> &'static str {
        match self { Self::Normal => "normal", Self::InlineSize => "inline-size", Self::Size => "size" }
    }
    fn parse(raw:&str) -> Option<Self> {
        if raw.eq_ignore_ascii_case("normal") { Some(Self::Normal) }
        else if raw.eq_ignore_ascii_case("inline-size") { Some(Self::InlineSize) }
        else if raw.eq_ignore_ascii_case("size") { Some(Self::Size) } else { None }
    }
}
impl Overflow {
    pub fn clips(self) -> bool {
        self != Self::Visible
    }
    pub fn scroll_container(self) -> bool {
        matches!(self, Self::Hidden | Self::Scroll | Self::Auto)
    }
    fn parse(raw: &str) -> Option<Self> {
        Some(match &*ascii_lower(raw) {
            "visible" => Self::Visible,
            "hidden" => Self::Hidden,
            "scroll" => Self::Scroll,
            "auto" => Self::Auto,
            "clip" => Self::Clip,
            _ => return None,
        })
    }
}

/// Computed CSS border style. `hidden` remains distinct from `none` because
/// it wins every collapsed-border conflict while suppressing the painted edge.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum BorderStyle {
    #[default]
    None,
    Hidden,
    Solid,
    Double,
    Dotted,
    Dashed,
    Groove,
    Ridge,
    Inset,
    Outset,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum OutlineStyle {
    Border(BorderStyle),
    Auto,
}
impl OutlineStyle {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Border(style) => style.as_str(),
            Self::Auto => "auto",
        }
    }
    pub const fn border_style(self) -> BorderStyle {
        match self {
            Self::Border(style) => style,
            Self::Auto => BorderStyle::Solid,
        }
    }
    fn parse(raw: &str) -> Option<Self> {
        if raw.eq_ignore_ascii_case("auto") {
            Some(Self::Auto)
        } else {
            BorderStyle::parse(raw)
                .filter(|style| *style != BorderStyle::Hidden)
                .map(Self::Border)
        }
    }
}
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Outline {
    pub width: f32,
    pub style: OutlineStyle,
    pub color: Option<Rgba>,
    pub offset: f32,
}
impl Outline {
    pub const INITIAL: Self = Self {
        width: 3.0,
        style: OutlineStyle::Border(BorderStyle::None),
        color: None,
        offset: 0.0,
    };
    pub fn used_width(self) -> f32 {
        if self.style.border_style().paints() {
            self.width
        } else {
            0.0
        }
    }
}

impl BorderStyle {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::None => "none",
            Self::Hidden => "hidden",
            Self::Solid => "solid",
            Self::Double => "double",
            Self::Dotted => "dotted",
            Self::Dashed => "dashed",
            Self::Groove => "groove",
            Self::Ridge => "ridge",
            Self::Inset => "inset",
            Self::Outset => "outset",
        }
    }

    pub const fn paints(self) -> bool {
        !matches!(self, Self::None | Self::Hidden)
    }

    /// CSS 2.1 collapsed-border style order, excluding the special `hidden`
    /// and `none` handling performed by the conflict resolver.
    pub const fn rank(self) -> u8 {
        match self {
            Self::None => 0,
            Self::Inset => 1,
            Self::Groove => 2,
            Self::Outset => 3,
            Self::Ridge => 4,
            Self::Dotted => 5,
            Self::Dashed => 6,
            Self::Solid => 7,
            Self::Double => 8,
            Self::Hidden => 9,
        }
    }

    pub const fn pattern(self) -> Option<BorderPattern> {
        match self {
            Self::Groove => Some(BorderPattern::Groove),
            Self::Ridge => Some(BorderPattern::Ridge),
            Self::Inset => Some(BorderPattern::Inset),
            Self::Outset => Some(BorderPattern::Outset),
            Self::Double => Some(BorderPattern::Double),
            Self::Dotted => Some(BorderPattern::Dotted),
            Self::Dashed => Some(BorderPattern::Dashed),
            _ => None,
        }
    }

    pub const fn from_pattern(pattern: BorderPattern) -> Self {
        match pattern {
            BorderPattern::Groove => Self::Groove,
            BorderPattern::Ridge => Self::Ridge,
            BorderPattern::Inset => Self::Inset,
            BorderPattern::Outset => Self::Outset,
            BorderPattern::Double => Self::Double,
            BorderPattern::Dashed => Self::Dashed,
            BorderPattern::Dotted => Self::Dotted,
        }
    }

    fn parse(raw: &str) -> Option<Self> {
        Some(match &*ascii_lower(raw) {
            "none" => Self::None,
            "hidden" => Self::Hidden,
            "solid" => Self::Solid,
            "double" => Self::Double,
            "dotted" => Self::Dotted,
            "dashed" => Self::Dashed,
            "groove" => Self::Groove,
            "ridge" => Self::Ridge,
            "inset" => Self::Inset,
            "outset" => Self::Outset,
            _ => return None,
        })
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum BackgroundAttachment {
    #[default]
    Scroll,
    Fixed,
    Local,
}
fn background_attachments(raw: &str) -> Option<Arc<[BackgroundAttachment]>> {
    let values = top_level_split(raw, b',', MAX_BACKGROUND_LAYERS)?
        .into_iter()
        .map(|value| {
            Some(match &*ascii_lower(value.trim()) {
                "scroll" => BackgroundAttachment::Scroll,
                "fixed" => BackgroundAttachment::Fixed,
                "local" => BackgroundAttachment::Local,
                _ => return None,
            })
        })
        .collect::<Option<Vec<_>>>()?;
    Some(values.into())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Display {
    Block,
    FlowRoot,
    Inline,
    InlineBlock,
    ListItem,
    Flex,
    Grid,
    Table,
    InlineTable,
    TableCaption,
    TableRowGroup,
    TableHeaderGroup,
    TableFooterGroup,
    TableColumn,
    TableColumnGroup,
    TableRow,
    TableCell,
    Contents,
    None,
}

impl Display {
    /// CSS 2.1 §9.7 changes the outer box while preserving table interiors.
    pub fn blockified(self) -> Self {
        match self {
            Self::InlineTable => Self::Table,
            Self::Inline | Self::InlineBlock | Self::TableCaption
                | Self::TableRowGroup | Self::TableHeaderGroup | Self::TableFooterGroup
                | Self::TableColumn | Self::TableColumnGroup | Self::TableRow
                | Self::TableCell => Self::Block,
            other => other,
        }
    }

    pub fn is_table(self) -> bool {
        matches!(self, Self::Table | Self::InlineTable)
    }

    pub fn is_table_row_group(self) -> bool {
        matches!(self, Self::TableRowGroup | Self::TableHeaderGroup | Self::TableFooterGroup)
    }

    pub fn is_table_column(self) -> bool {
        matches!(self, Self::TableColumn | Self::TableColumnGroup)
    }
}

/// CSS `list-style-type` values supported by the shared marker renderer.
/// Other counter styles are retained by name and reported as an unsupported
/// generated-content feature when a marker is actually painted.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ListStyleType {
    Disc,
    Circle,
    Square,
    Decimal,
    DecimalLeadingZero,
    LowerRoman,
    UpperRoman,
    LowerAlpha,
    UpperAlpha,
    None,
    String(Arc<str>),
    Unsupported(Arc<str>),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TextDecorationStyle { Solid, Double, Dotted, Dashed, Wavy }
impl TextDecorationStyle {
    pub fn parse(raw: &str) -> Option<Self> { Some(match raw {
        "solid" => Self::Solid, "double" => Self::Double, "dotted" => Self::Dotted,
        "dashed" => Self::Dashed, "wavy" => Self::Wavy, _ => return None,
    }) }
    pub fn as_str(self) -> &'static str { match self {
        Self::Solid => "solid", Self::Double => "double", Self::Dotted => "dotted",
        Self::Dashed => "dashed", Self::Wavy => "wavy",
    } }
}

