#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct TextUnderlinePosition(pub u8);
impl TextUnderlinePosition {
    pub fn parse(raw: &str) -> Option<Self> {
        if raw.trim().eq_ignore_ascii_case("auto") { return Some(Self(0)); }
        let mut bits = 0;
        let mut vertical = false;
        let mut horizontal = false;
        for part in components(raw)? {
            match &*ascii_lower(part) {
                "from-font" if !horizontal => { horizontal = true; bits |= 8; }
                "under" if !horizontal => { horizontal = true; bits |= 1; }
                "left" if !vertical => { vertical = true; bits |= 2; }
                "right" if !vertical => { vertical = true; bits |= 4; }
                _ => return None,
            }
        }
        (vertical || horizontal).then_some(Self(bits))
    }
    pub fn serialize(self) -> String {
        let mut value = String::new();
        if self.0 & 1 != 0 { value.push_str("under"); }
        else if self.0 & 8 != 0 { value.push_str("from-font"); }
        if self.0 & 6 != 0 {
            if !value.is_empty() { value.push(' '); }
            value.push_str(if self.0 & 2 != 0 { "left" } else { "right" });
        }
        if value.is_empty() { value.push_str("auto"); }
        value
    }
}

pub(super) fn serialize_text_decoration_line(bits: u8) -> String {
    let mut result = String::new();
    for (bit, name) in [(1,"underline"),(2,"overline"),(4,"line-through"),(8,"blink")] {
        if bits & bit != 0 { if !result.is_empty() { result.push(' '); } result.push_str(name); }
    }
    if result.is_empty() { result.push_str("none"); }
    result
}

fn text_decoration_line(raw: &str) -> Option<u8> {
    let parts = components(raw)?;
    if parts.len() == 1 && parts[0].eq_ignore_ascii_case("none") { return Some(0); }
    let mut bits = 0;
    for part in parts {
        let bit = match &*ascii_lower(part) { "underline" => 1, "overline" => 2,
            "line-through" => 4, "blink" => 8, _ => return None };
        if bits & bit != 0 { return None; } bits |= bit;
    }
    (bits != 0).then_some(bits)
}

fn text_decoration_shorthand(raw: &str) -> Option<[Value; 4]> {
    let mut lines = None;
    let mut style = None;
    let mut paint = None;
    let mut thickness = None;
    for part in components(raw)? {
        let lowered = ascii_lower(part);
        if let Some(bit) = text_decoration_line(&lowered) {
            if bit == 0 { if lines.is_some() { return None; } lines = Some(0); }
            else { let previous = lines.unwrap_or(0); if lines == Some(0) || previous & bit != 0 { return None; } lines = Some(previous | bit); }
        } else if let Some(parsed) = TextDecorationStyle::parse(&lowered) {
            if style.replace(parsed).is_some() { return None; }
        } else if let Some(value) = decoration_length_value(214, &lowered) {
            if thickness.replace(value).is_some() { return None; }
        } else {
            if paint.is_some() { return None; }
            paint = Some(if lowered == "currentcolor" { Value::TextDecorationColor(None) }
                else { color_value(203,part)? });
        }
    }
    if lines.is_none() && style.is_none() && paint.is_none() && thickness.is_none() { return None; }
    Some([Value::TextDecoration(lines.unwrap_or(0)),
        Value::TextDecorationStyle(style.unwrap_or(TextDecorationStyle::Solid)),
        paint.unwrap_or(Value::TextDecorationColor(None)),
        thickness.unwrap_or(Value::DecorationLength(214, DecorationLength::Auto))])
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ListStylePosition {
    Inside,
    Outside,
}

fn list_style_type(raw: &str) -> Option<ListStyleType> {
    let raw = raw.trim();
    Some(match &*ascii_lower(raw) {
        "disc" => ListStyleType::Disc,
        "circle" => ListStyleType::Circle,
        "square" => ListStyleType::Square,
        "decimal" => ListStyleType::Decimal,
        "decimal-leading-zero" => ListStyleType::DecimalLeadingZero,
        "lower-roman" => ListStyleType::LowerRoman,
        "upper-roman" => ListStyleType::UpperRoman,
        "lower-alpha" | "lower-latin" => ListStyleType::LowerAlpha,
        "upper-alpha" | "upper-latin" => ListStyleType::UpperAlpha,
        "none" => ListStyleType::None,
        _ if matches!(raw.as_bytes().first(), Some(b'\'' | b'"')) => {
            ListStyleType::String(Arc::from(css_string(raw)?))
        }
        _ => ListStyleType::Unsupported(Arc::from(parse_counter_ident(raw)?)),
    })
}

fn list_style_position(raw: &str) -> Option<ListStylePosition> {
    Some(match &*ascii_lower(raw.trim()) {
        "inside" => ListStylePosition::Inside,
        "outside" => ListStylePosition::Outside,
        _ => return None,
    })
}

fn list_style_image(raw: &str) -> Option<Option<Arc<str>>> {
    let raw = raw.trim();
    if raw.eq_ignore_ascii_case("none") {
        Some(None)
    } else {
        if let Some(url)=background_url(raw) {return Some(Some(url));}
        let images=background_images(raw,Style::initial().color,None)?;
        (images.len()==1).then(||Some(Arc::from(raw)))
    }
}

/// Marker image functions use the same validated image/computed serializer as
/// backgrounds. URL-only markers retain their existing compact source carrier.
fn marker_image_source(image:&BackgroundImage)->Option<Arc<str>> {
    match image {BackgroundImage::None=>None,BackgroundImage::Url(url)=>Some(url.clone()),
        _=>computed_values::image(image,0).map(Arc::from)}
}
pub(crate) fn computed_image_source(raw:&str,color:Rgba)->BackgroundImage {
    background_images(raw,color,None).and_then(|images|images.first().cloned())
        .unwrap_or_else(||BackgroundImage::Url(Arc::from(raw)))
}
pub(crate) fn computed_marker_image(style:&Style)->Option<BackgroundImage> {
    style.list_style_image.as_deref().map(|raw|computed_image_source(raw,style.color))
}

fn list_style_shorthand(raw: &str) -> Option<(ListStyleType, ListStylePosition, Option<Arc<str>>)> {
    let parts = components_bounded(raw, MAX_GENERATED_CONTENT_BYTES)?;
    if parts.is_empty() || parts.len() > 3 {
        return None;
    }

    let mut marker = None;
    let mut position = None;
    let mut none_count = 0usize;
    let mut image = None;
    let mut image_specified = false;
    for part in parts {
        if let Some(value) = list_style_position(part) {
            if position.replace(value).is_some() {
                return None;
            }
        } else if let Some(Some(value)) = list_style_image(part) {
            if image.replace(value).is_some() {
                return None;
            }
            image_specified = true;
        } else if part.eq_ignore_ascii_case("none") {
            none_count += 1;
        } else {
            let value = list_style_type(part)?;
            if marker.replace(value).is_some() {
                return None;
            }
        }
    }

    // `none` is ambiguous in the shorthand. Assign it to still-unfilled
    // image/type slots in canonical order, with a lone `none` disabling the
    // marker type as required by the shorthand special case.
    if none_count > 2 || none_count > usize::from(marker.is_none()) + usize::from(!image_specified)
    {
        return None;
    }
    if none_count != 0 && marker.is_none() {
        marker = Some(ListStyleType::None);
        none_count -= 1;
    }
    if none_count != 0 && !image_specified {
        none_count -= 1;
    }
    if none_count != 0 {
        return None;
    }

    Some((
        marker.unwrap_or(ListStyleType::Disc),
        position.unwrap_or(ListStylePosition::Outside),
        image,
    ))
}

fn html_list_style_type(tag:&str,value: &str) -> Option<ListStyleType> {
    if matches!(tag,"ol"|"li") {
        let kind=match value {
        "1" => ListStyleType::Decimal,
        "a" => ListStyleType::LowerAlpha,
        "A" => ListStyleType::UpperAlpha,
        "i" => ListStyleType::LowerRoman,
        "I" => ListStyleType::UpperRoman,
            _=>ListStyleType::None,
        };
        if value=="1"||matches!(value,"a"|"A"|"i"|"I") {return Some(kind);}
    }
    if matches!(tag,"ul"|"li") {
        if value.eq_ignore_ascii_case("none") {return Some(ListStyleType::None);}
        if value.eq_ignore_ascii_case("disc") {return Some(ListStyleType::Disc);}
        if value.eq_ignore_ascii_case("circle") {return Some(ListStyleType::Circle);}
        if value.eq_ignore_ascii_case("square") {return Some(ListStyleType::Square);}
    }
    None
}

fn clamp_css_counter(value: i64) -> i64 {
    value.clamp(-MAX_COUNTER_VALUE, MAX_COUNTER_VALUE)
}

