#[derive(Clone, Debug)]
pub struct Style {
    extras: Option<Arc<StyleExtras>>,
    custom: Option<Arc<[(String, Option<String>)]>>,
    pub display: Display,
    pub opacity: f32,
    pub color: Rgba,
    pub background: Rgba,
    pub width: Option<f32>,
    pub min_width: f32,
    pub max_width: Option<f32>,
    pub height: Option<f32>,
    pub margin: f32,
    pub padding: f32,
    pub font_size: f32,
    pub border_radius: f32,
    pub border_width: f32,
    pub border_color: Rgba,
    pub border_solid: bool,
    pub border_style: BorderStyle,
    pub overflow_clip: bool,
    pub line_height: LineHeight,
    pub flex_direction: FlexDirection,
    pub flex_wrap: bool,
    pub justify_content: JustifyContent,
    pub align_items: AlignItems,
    pub gap: f32,
    pub flex_grow: f32,
    pub flex_shrink: f32,
    pub flex_basis: Option<f32>,
    pub box_sizing: BoxSizing,
    pub table_fixed: bool,
    /// Horizontal and vertical table border spacing.
    pub border_spacing: [f32; 2],
    // HTML table association carried through the composed cascade, outside
    // CSS inheritance. A new table formatting box ends the prior association.
    html_cell_padding_hint: Option<f32>,
    pub grid_column: GridPlacement,
    pub grid_row: GridPlacement,
}

fn arcs_equal<T: ?Sized + PartialEq>(a: &Option<Arc<T>>, b: &Option<Arc<T>>) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(a), Some(b)) => Arc::ptr_eq(a, b) || a == b,
        _ => false,
    }
}

impl PartialEq for Style {
    fn eq(&self, other: &Self) -> bool {
        let Style {
            extras,
            custom,
            display,
            opacity,
            color,
            background,
            width,
            min_width,
            max_width,
            height,
            margin,
            padding,
            font_size,
            border_radius,
            border_width,
            border_color,
            border_solid,
            border_style,
            overflow_clip,
            line_height,
            flex_direction,
            flex_wrap,
            justify_content,
            align_items,
            gap,
            flex_grow,
            flex_shrink,
            flex_basis,
            box_sizing,
            table_fixed,
            border_spacing,
            html_cell_padding_hint,
            grid_column,
            grid_row,
        } = self;
        *display == other.display
            && *opacity == other.opacity
            && *color == other.color
            && *background == other.background
            && *width == other.width
            && *min_width == other.min_width
            && *max_width == other.max_width
            && *height == other.height
            && *margin == other.margin
            && *padding == other.padding
            && *font_size == other.font_size
            && *border_radius == other.border_radius
            && *border_width == other.border_width
            && *border_color == other.border_color
            && *border_solid == other.border_solid
            && *border_style == other.border_style
            && *overflow_clip == other.overflow_clip
            && *line_height == other.line_height
            && *flex_direction == other.flex_direction
            && *flex_wrap == other.flex_wrap
            && *justify_content == other.justify_content
            && *align_items == other.align_items
            && *gap == other.gap
            && *flex_grow == other.flex_grow
            && *flex_shrink == other.flex_shrink
            && *flex_basis == other.flex_basis
            && *box_sizing == other.box_sizing
            && *table_fixed == other.table_fixed
            && *border_spacing == other.border_spacing
            && *html_cell_padding_hint == other.html_cell_padding_hint
            && *grid_column == other.grid_column
            && *grid_row == other.grid_row
            && arcs_equal(custom, &other.custom)
            && arcs_equal(extras, &other.extras)
    }
}

