    /// A cheap check for the rare values that need ancestor query-container
    /// context. The flag is captured when the sparse expression is created,
    /// so ordinary computed-style reads do not parse or drain expression data.
    pub fn has_query_container_dependencies(&self) -> bool {
        self.registered_query.is_some() || self.font.unresolved_stretch.as_ref().is_some_and(|expression| expression.contains_unit(container_unit)) || font_features_query_pending(self.font.feature_settings.as_deref()) || self.font.unresolved_style.as_ref().is_some_and(|expression| expression.contains_unit(container_unit)) ||
            self.relative_expressions.iter().any(|expression| expression.query_dependent)
    }
    /// Resolve query-dependent lengths without inventing a containing-block
    /// percentage basis. Mixed percentages stay retained until layout supplies it.
    fn resolve_from_font_adjust(&mut self, text: Option<&dyn TextShaper>) {
        let Some(adjust) = self.font.size_adjust.filter(|adjust| matches!(adjust.value, FontSizeAdjustValue::FromFont)) else { return; };
        if self.font_query_context_pending() { return; }
        let Some(metric) = text.and_then(|text| text.first_available_font_metric(self.font_spec(), adjust.metric)) else { return; };
        self.font.size_adjust = metric.filter(|value| value.is_finite() && *value >= 0.0)
            .map(|value| FontSizeAdjust { metric: adjust.metric, value: FontSizeAdjustValue::Number(value) });
    }

    pub fn resolve_query_context(&mut self, query: ContainerUnitContext) -> bool {
        self.resolve_query_context_with_text(query,None)
    }
    /// Resolve current-font consumers using actual backend metrics when supplied.
