/// UA keyword sizes share one table with HTML's legacy font-size hints.
/// Keywords remain specified values until cascade; Style stores only pixels.
#[derive(Clone, Copy, Debug)]
enum FontSizeKeyword {
    Absolute(u8),
    Larger,
    Smaller,
}

impl FontSizeKeyword {
    const NAMES: [&'static str; 8] = [
        "xx-small", "x-small", "small", "medium", "large", "x-large", "xx-large", "xxx-large",
    ];
    const SIZES: [f32; 8] = [9.6, 12.0, 16.0 * 8.0 / 9.0, 16.0, 19.2, 24.0, 32.0, 48.0];

    fn parse(raw: &str) -> Option<Self> {
        if raw.eq_ignore_ascii_case("larger") {
            Some(Self::Larger)
        } else if raw.eq_ignore_ascii_case("smaller") {
            Some(Self::Smaller)
        } else {
            Self::NAMES.iter().position(|name| raw.eq_ignore_ascii_case(name))
                .map(|index| Self::Absolute(index as u8))
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Absolute(index) => Self::NAMES[usize::from(index)],
            Self::Larger => "larger",
            Self::Smaller => "smaller",
        }
    }

    fn resolve(self, inherited: f32) -> f32 {
        match self {
            Self::Absolute(index) => Self::SIZES[usize::from(index)],
            Self::Larger => Self::SIZES.iter().copied().find(|size| *size > inherited)
                .unwrap_or(inherited * 1.2),
            Self::Smaller => Self::SIZES.iter().rev().copied().find(|size| *size < inherited)
                .unwrap_or(inherited / 1.2),
        }
    }
}

/// HTML font size parses an optional sign and decimal prefix, then clamps to
/// 1..7. Relative attributes are based on the legacy default size of 3.
fn legacy_font_size(raw: &str) -> Option<f32> {
    let input = raw.trim_start_matches(|ch: char| ch.is_ascii_whitespace());
    let (relative, negative, digits) = if let Some(rest) = input.strip_prefix('+') {
        (true, false, rest)
    } else if let Some(rest) = input.strip_prefix('-') {
        (true, true, rest)
    } else {
        (false, false, input)
    };
    let mut value = 0u8;
    let mut any = false;
    for digit in digits.bytes().take_while(u8::is_ascii_digit) {
        any = true;
        value = value.saturating_mul(10).saturating_add(digit - b'0');
    }
    if !any { return None; }
    let value = if relative {
        if negative { 3u8.saturating_sub(value) } else { 3u8.saturating_add(value) }
    } else { value }.clamp(1, 7);
    let index = if value == 1 { 0 } else { value };
    Some(FontSizeKeyword::Absolute(index).resolve(16.0))
}

