    #[test]
    fn specification_columns_share_shorthand_numeric_query_and_cssom_authority() {
        for (raw,expected) in [("0","0px"),("2 60px","60px 2"),("auto 2","2"),("60px auto","60px"),("auto auto","auto")] {
            assert_eq!(declaration_value(&alloc::format!("columns:{raw}"),"columns").unwrap().unwrap().0,expected);
        }
        assert_eq!(serialize_cssom_property_value("column-width","0").unwrap(),"0px");
        for raw in ["-1px","2px 3px","2 3","auto auto auto","calc(1deg)"] {
            assert!(declaration_value(&alloc::format!("columns:{raw}"),"columns").unwrap().is_none(),"{raw}");
        }
        let index=StyleIndex::new(Vec::new());
        let mut parent=compute(&element("font-size:20px;columns:calc(1em + 10cqw) 2"),None,&index).unwrap();
        assert!(parent.property_query_context_pending("column-width"));
        let query=ContainerUnitContext{width:ContainerUnitBasis::Size(300.0),height:ContainerUnitBasis::Size(100.0),inline:ContainerUnitBasis::Size(300.0),block:ContainerUnitBasis::Size(100.0),..ContainerUnitContext::default()};
        assert!(parent.resolve_query_context(query));
        assert_eq!(parent.column_width.serialize().unwrap(),"50px");
        assert_eq!(parent.column_count,Some(2));
        let child=compute(&element("font-size:40px;columns:inherit"),Some(&parent),&index).unwrap();
        assert_eq!(child.column_width.serialize().unwrap(),"50px");
        assert_eq!(child.column_count,Some(2));
        assert_eq!(columns::used(&parent,125.0,0.0,0.0,5.0),(2,60.0));
        assert_eq!(columns::used(&parent,100.0,0.0,0.0,5.0),(1,100.0));
        let keyword=compute(&element("column-width:min-content"),None,&index).unwrap();
        assert_eq!(columns::used(&keyword,125.0,20.0,100.0,5.0),(5,21.0));
        let percentage=compute(&element("columns:calc(60px + 50%) 2"),None,&index).unwrap();
        assert_eq!(columns::intrinsic_inline(&percentage,20.0,40.0,false),96.0,"cyclic preferred percentage width behaves as auto; do not resolve against measured contents");
        assert_eq!(columns::used(&percentage,300.0,20.0,40.0,5.0),(1,300.0));
        let fit=compute(&element("columns:fit-content(50%) 2;column-gap:5px"),None,&index).unwrap();
        assert_eq!(columns::intrinsic_inline(&fit,20.0,40.0,false),85.0,"indefinite fit-content percentage behaves as fit-content");
        let infinite=compute(&element("column-width:calc(infinity * 1px)"),None,&index).unwrap();
        assert_eq!(infinite.column_width.optimal(Some(100.0),0.0,0.0),Some(f32::MAX));
        let nan=compute(&element("column-width:calc(NaN * 1px)"),None,&index).unwrap();
        assert_eq!(nan.column_width.optimal(Some(100.0),0.0,0.0),Some(0.0));
        let bounded=compute(&element("columns:100"),None,&index).unwrap();
        assert_eq!(bounded.column_count,Some(100),"computed declarations retain their valid count before bounded layout work");
    }

    #[test]
    fn specification_import_headers_keep_leading_layers_and_reject_interleaved_imports() {
        let leading=imports("@layer first,second;@import url(a.css);@import url(b.css);.body{}").unwrap();
        assert_eq!(leading.iter().map(|rule|rule.url.as_ref()).collect::<Vec<_>>(),vec!["a.css","b.css"]);
        let separated=imports("@import url(a.css);@layer boundary;@import url(b.css);.body{}").unwrap();
        assert_eq!(separated.iter().map(|rule|rule.url.as_ref()).collect::<Vec<_>>(),vec!["a.css"],"layer statements close an existing import header before fetch admission");
        assert!(imports("@layer first{}.body{}@import url(late.css);").unwrap().is_empty(),"layer blocks are ordinary rules");
        assert!(imports("@namespace n url(urn:n);@import url(late.css);").unwrap().is_empty(),"namespace header follows imports");
    }

    #[test]
    fn specification_text_shadow_query_dependencies_reuse_computed_length_context() {
        let index=StyleIndex::new(Vec::new());
        let mut style=compute(&element("font-size:20px;color:blue;text-shadow:currentColor 10cqw 1em 5cqh;box-shadow:red 5cqi 2px"),None,&index).unwrap();
        assert!(style.property_query_context_pending("text-shadow"));assert!(style.property_query_context_pending("box-shadow"));
        assert!(!style.property_query_context_pending("color"));
        let query=ContainerUnitContext{width:ContainerUnitBasis::Size(300.0),height:ContainerUnitBasis::Size(200.0),
            inline:ContainerUnitBasis::Size(300.0),block:ContainerUnitBasis::Size(200.0),..ContainerUnitContext::default()};
        assert!(style.resolve_query_context(query));
        let shadow=style.text_shadows.as_ref().unwrap()[0];assert_eq!((shadow.offset_x,shadow.offset_y,shadow.blur),(30.0,20.0,10.0));
        assert_eq!(style.shadows.as_ref().unwrap()[0].offset_x,15.0);
        let inherited=compute(&element("font-size:40px;color:red"),Some(&style),&index).unwrap();
        assert_eq!(inherited.text_shadows.as_ref().unwrap()[0].offset_y,20.0,"inherited computed lengths retain the declaring font/container context");
        assert_eq!(inherited.text_shadows.as_ref().unwrap()[0].color,inherited.color);
        assert!(animation_shadow_query_dependent("currentColor calc(1em + 10cqw) 0"));
        assert!(!animation_shadow_query_dependent("rgb(10%, 20%, 30%) 1em 0"));
        assert!(parse_animation_shadows_with_query("text-shadow","10cqw 0",&style,index.environment,None,ContainerUnitContext::default()).is_none(),"unknown eligible query axes never silently use viewport fallback");
        let environment=MediaEnvironment{width:400.0,height:200.0,..MediaEnvironment::default()};
        assert_eq!(parse_animation_shadows_with_query("text-shadow","10cqw 0",&style,environment,None,ContainerUnitContext::no_container(environment)).unwrap()[0].offset_x,40.0,"no eligible ancestor uses the actual small viewport");
    }

    #[test]
    fn specification_text_shadow_grammar_computed_context_inheritance_and_cascade() {
        let index=StyleIndex::new(Vec::new());
        let parent=compute(&element("color:blue;font-size:10px;text-shadow:currentColor 1em -2px 0.5em,red 0 0"),None,&index).unwrap();
        let values=parent.text_shadows.as_ref().unwrap();
        assert_eq!((values[0].offset_x,values[0].offset_y,values[0].blur,values[0].spread,values[0].inset),(10.0,-2.0,5.0,0.0,false));
        assert_eq!(values[0].color,parent.color);
        let child=compute(&element("color:red;font-size:30px"),Some(&parent),&index).unwrap();
        assert_eq!(child.text_shadows.as_ref().unwrap()[0].offset_x,10.0,"inherited lengths retain the parent font basis");
        assert_eq!(child.text_shadows.as_ref().unwrap()[0].color,child.color,"inherited currentcolor resolves against the descendant");
        assert_eq!(child.text_shadows.as_ref().unwrap()[1],parent.text_shadows.as_ref().unwrap()[1]);
        for source in ["text-shadow:inherit","text-shadow:unset"] {
            assert_eq!(compute(&element(source),Some(&parent),&index).unwrap().text_shadows,parent.text_shadows);
        }
        for source in ["text-shadow:none","text-shadow:initial","all:initial"] {
            assert!(compute(&element(source),Some(&parent),&index).unwrap().text_shadows.is_none());
        }
        for invalid in ["1px","1px 2px 3px 4px","1px 2px inset","1px 2px -1px","1% 2px","red blue 1px 2px","1px red 2px"] {
            assert!(!supports_declaration("text-shadow",invalid),"{invalid}");
        }
        let winning=compute(&element("text-shadow:green 1px 2px!important;text-shadow:red 9px 9px"),None,&index).unwrap();
        assert_eq!(winning.text_shadows.as_ref().unwrap()[0].offset_x,1.0);
        let serialized=parent.computed_css_value("text-shadow",computed_values::ComputedValueContext::default()).unwrap();
        assert_eq!(compute(&element(&alloc::format!("text-shadow:{serialized}")),None,&index).unwrap().text_shadows,parent.text_shadows);
        let mut declaration=DeclarationBlock::parse("text-shadow:1em 2px blue").unwrap();
        assert!(!declaration.set("text-shadow","inset 0 0",false).unwrap());
        assert!(declaration.set("text-shadow","none",false).unwrap());
        assert_eq!(compute(&element(&declaration.serialize().unwrap()),Some(&parent),&index).unwrap().text_shadows,None);
    }

    #[test]
    fn specification_heading_selectors_share_levels_namespace_and_integer_list_grammar() {
        let mut document=crate::html::parse("<!doctype html><div headingoffset=2 id=host><h1 id=a></h1><div headingreset><h1 id=b></h1></div></div><p id=c role=heading aria-level=3></p>",128).unwrap();
        let find=|doc:&Document,id|crate::selector::get_element_by_id(doc,doc.root(),id).unwrap().unwrap();
        let a=find(&document,"a");let b=find(&document,"b");let c=find(&document,"c");
        assert!(crate::selector::matches(&document,a,":heading(0, +03, -1, 99999)").unwrap());
        assert!(crate::selector::matches(&document,b,":heading(1)").unwrap());
        assert!(!crate::selector::matches(&document,c,":heading").unwrap());
        assert!(crate::selector::matches(&document,find(&document,"host"),":has(:heading(3))").unwrap());
        let index=StyleIndex::new(parse(":heading(3){color:red}:heading(3)::after{content:'level'}").unwrap());
        let style=compute_node(&document,a,None,&index).unwrap();assert_eq!(style.color,Rgba{r:255,g:0,b:0,a:255});
        assert!(index.compute_pseudo(&document,a,&style,PseudoElement::After,None).unwrap().is_some());
        document.set_attribute(find(&document,"host"),"headingoffset","4").unwrap();
        assert!(!crate::selector::matches(&document,a,":heading(3)").unwrap());assert!(crate::selector::matches(&document,a,":heading(5)").unwrap());
        let prefixed=document.create(NodeKind::Element{namespace:Namespace::Html,name:"h:h1".into(),attributes:Vec::new()}).unwrap();
        assert!(crate::selector::matches(&document,prefixed,":heading(1)").unwrap());
        let foreign=document.create(NodeKind::Element{namespace:Namespace::Svg,name:"h1".into(),attributes:Vec::new()}).unwrap();assert!(!crate::selector::matches(&document,foreign,":heading").unwrap());
        for selector in [":heading",":heading(+1)",":heading(-1)",":heading(0,1,2)",":heading(999999999999999999999999)",":heading(1/**/, 2)"] {assert!(parse_selector(selector,0).is_ok(),"{selector}");}
        for selector in [":heading()",":heading(1.0)",":heading(1e0)",":heading(n)",":heading(1 2)",":heading(1,)",":heading(,1)",":heading(calc(1))",":heading(var(--level))","::heading"] {assert!(parse_selector(selector,0).is_err(),"{selector}");}
    }

