    #[test]
    fn specification_heading_ua_font_and_em_margins_use_levels_final_font_and_logical_axes() {
        let index=StyleIndex::new(Vec::new());
        let parent=compute(&element("font-size:20px"),None,&index).unwrap();
        let document=crate::html::parse("<!doctype html><h1 id=a>A</h1><h2 id=b headingoffset=3>B</h2><h1 id=c style='font-size:30px;writing-mode:vertical-rl;direction:rtl'>C</h1><h1 id=d style='all:initial'>D</h1><section headingoffset=3><div headingreset><h1 id=e>E</h1></div></section>",128).unwrap();
        let style=|id|{let node=crate::selector::get_element_by_id(&document,document.root(),id).unwrap().unwrap();compute_node(&document,node,Some(&parent),&index).unwrap()};
        let a=style("a");assert_eq!(a.font_size,40.0);assert_eq!(a.font.weight,700);assert!((a.margin_sides[0]-26.8).abs()<0.001);
        let b=style("b");assert!((b.font_size-16.6).abs()<0.001);assert!((b.margin_sides[2]-27.722).abs()<0.001);
        let c=style("c");assert_eq!(c.font_size,30.0);assert_eq!((c.margin_sides[0],c.margin_sides[2]),(0.0,0.0));
        assert!((c.margin_sides[1]-20.1).abs()<0.001&&(c.margin_sides[3]-20.1).abs()<0.001);
        let d=style("d");assert_eq!(d.font_size,16.0);assert_eq!(d.font.weight,400);assert_eq!(d.margin_sides,[0.0;4]);
        assert_eq!(style("e").font_size,40.0,"headingreset cuts off outer offsets before UA font selection");
    }

    #[test]
    fn specification_ua_logical_edges_preserve_author_aliases_and_reverted_layer_sources() {
        let mut kind=element("font-size:30px;margin-top:7px;margin-block-start:revert");
        if let NodeKind::Element{name,..}=&mut kind {*name="p".into();}
        let index=StyleIndex::new(Vec::new());
        let style=compute(&kind,None,&index).unwrap();assert_eq!(style.margin_sides,[30.0,0.0,30.0,0.0]);
        if let NodeKind::Element{attributes,..}=&mut kind {attributes[0].1="margin-block-start:5px;margin-top:revert".into();}
        assert_eq!(compute(&kind,None,&index).unwrap().margin_sides[0],16.0);
        if let NodeKind::Element{attributes,..}=&mut kind {attributes[0].1="margin-block-start:revert;margin-top:7px".into();}
        assert_eq!(compute(&kind,None,&index).unwrap().margin_sides[0],7.0,"a later author declaration wins the paired cascade before rollback");
        if let NodeKind::Element{attributes,..}=&mut kind {attributes[0].1="font-size:30px;all:revert".into();}
        assert_eq!(compute(&kind,None,&index).unwrap().margin_sides,[16.0,0.0,16.0,0.0]);
        if let NodeKind::Element{attributes,..}=&mut kind {attributes[0].1="all:initial".into();}
        assert_eq!(compute(&kind,None,&index).unwrap().margin_sides,[0.0;4]);
        if let NodeKind::Element{attributes,..}=&mut kind {attributes.clear();}
        for (css,expected) in [
            ("@layer a,b;@layer a{p{margin-block-start:5px;margin-top:7px}}@layer b{p{margin-block-start:9px;margin-block-start:revert-layer}}",7.0),
            ("@layer a,b;@layer a{p{margin-block-start:5px}}@layer b{p{margin-top:9px;margin-top:revert-layer}}",5.0),
            ("p{margin-top:7px!important;margin-block-start:revert}",7.0),
        ] {assert_eq!(compute(&kind,None,&StyleIndex::new(parse(css).unwrap())).unwrap().margin_sides[0],expected,"effective alias source for {css}");}
    }

    #[test]
    fn specification_html_flow_and_list_defaults_follow_namespace_descendants_and_author_hints() {
        let index=StyleIndex::new(Vec::new());
        let parent=compute(&element("font-size:20px;writing-mode:vertical-rl;direction:rtl"),None,&index).unwrap();
        let mut document=crate::html::parse("<!doctype html><ul id=a><li id=item><ul id=b><li><menu id=c></menu></li></ul></li><div id=host></div></ul><dl><dd id=d><ul id=e></ul></dd></dl><blockquote id=f></blockquote><pre id=g style='font-size:24px' wrap></pre><ol id=h type=circle></ol><ul id=i type=A></ul><li id=j type=NoNe></li>",128).unwrap();
        let get=|document:&Document,id|crate::selector::get_element_by_id(document,document.root(),id).unwrap().unwrap();
        let style=|document:&Document,id|compute_node(document,get(document,id),Some(&parent),&index).unwrap();
        let a=style(&document,"a");assert_eq!(a.margin_sides,[0.0,20.0,0.0,20.0]);assert_eq!(a.padding_sides(),[0.0,0.0,40.0,0.0]);assert_eq!(a.list_style_type,ListStyleType::Disc);
        let b=style(&document,"b");assert_eq!(b.margin_sides,[0.0;4]);assert_eq!(b.list_style_type,ListStyleType::Circle);
        assert_eq!(style(&document,"c").list_style_type,ListStyleType::Square);
        assert_eq!(style(&document,"d").margin_sides,[0.0,0.0,40.0,0.0]);
        let e=style(&document,"e");assert_eq!(e.margin_sides,[0.0;4]);assert_eq!(e.list_style_type,ListStyleType::Disc,"dl suppresses margins but does not select circle markers");
        assert_eq!(style(&document,"f").margin_sides,[40.0,20.0,40.0,20.0]);
        let g=style(&document,"g");assert_eq!(g.margin_sides,[0.0,24.0,0.0,24.0]);assert_eq!(g.white_space,WhiteSpace::PreWrap);
        assert_eq!(g.font.families.as_deref(),Some(&[FontFamily::Generic(GenericFontFamily::Monospace)][..]));
        assert_eq!(style(&document,"h").list_style_type,ListStyleType::Decimal);assert_eq!(style(&document,"i").list_style_type,ListStyleType::Disc);assert_eq!(style(&document,"j").list_style_type,ListStyleType::None);
        let host=get(&document,"host");let shadow=document.attach_shadow(host,crate::ShadowMode::Open).unwrap();
        let list=document.create(NodeKind::Element{namespace:Namespace::Html,name:"ul".into(),attributes:Vec::new()}).unwrap();document.append(shadow,list).unwrap();
        let style=compute_node(&document,list,Some(&parent),&index).unwrap();assert_eq!(style.list_style_type,ListStyleType::Disc);assert_eq!(style.margin_sides,[0.0,20.0,0.0,20.0],"UA descendant selectors do not cross the shadow root");
        let quirks=crate::html::parse("<li id=outside></li><ul><li id=inside></li></ul>",64).unwrap();
        assert_eq!(compute_node(&quirks,get(&quirks,"outside"),None,&index).unwrap().list_style_position,ListStylePosition::Inside);
        assert_eq!(compute_node(&quirks,get(&quirks,"inside"),None,&index).unwrap().list_style_position,ListStylePosition::Outside);
    }
    #[test]
    fn animation_comments_preserve_component_boundaries_and_strings() {
        let shorthand = animation_values("animation", "fade/* boundary */100ms linear /* tail */").unwrap();
        assert_eq!(shorthand[0].1, "fade");
        assert_eq!(shorthand[1].1, "100ms");
        assert_eq!(animation_values("animation-name", "\"fade/*literal*/\"/* tail */").unwrap()[0].1,
            r"fade\/\*literal\*\/");
        assert_eq!(animation_values("animation-duration", "100ms/* tail */").unwrap()[0].1, "100ms");
        assert!(animation_values("animation", "fade 100ms/* boundary */200ms 300ms").is_none());
        assert!(animation_values("animation-duration", "-100ms/* tail */").is_none());
        assert!(animation_values("animation", "fade 100ms /* unterminated").is_none());
        assert!(animation_values("animation", "fa/* boundary */de 100ms").is_none());
    }

    #[test]
    fn specification_animation_computed_controls_reuse_font_query_and_reset_provenance(){
        let index=StyleIndex::new(Vec::new());
        let mut style=compute(&element("font-size:24px;animation:fade calc(10s + sign(2cqw - 10px) * 5s) steps(calc(2 + sign(1em - 20px)));animation-iteration-count:calc(10 + sign(2cqw - 10px) * 5);animation-range:entry calc(1em + 10%) exit 90%;animation-timeline:view(inline 1em 10%)"),None,&index).unwrap();
        let query=ContainerUnitContext{width:ContainerUnitBasis::Size(200.0),..ContainerUnitContext::no_container(index.environment)};
        assert!(style.resolve_query_context(query));
        assert_eq!(style.animation[1].as_deref(),Some("5s"));
        assert_eq!(style.animation[3].as_deref(),Some("steps(3)"));
        assert_eq!(style.animation[4].as_deref(),Some("5"));
        assert_eq!(style.animation[15].as_deref(),Some("entry calc(10% + 24px)"));
        assert_eq!(style.animation[9].as_deref(),Some("view(inline 24px 10%)"));
        let reset=compute(&element("animation-composition:add;animation-range:exit;animation-delay-end:1s;animation:fade 2s"),None,&index).unwrap();
        assert_eq!(reset.animation[8].as_deref(),Some("replace"));
        assert_eq!(reset.animation[15].as_deref(),Some("normal"));
        assert_eq!(reset.animation[16].as_deref(),Some("normal"));
        assert_eq!(reset.animation[17].as_deref(),Some("0s"));
        let inherited=compute(&element("animation-range:inherit;animation-delay:inherit"),Some(&style),&index).unwrap();
        assert_eq!(inherited.animation[15],style.animation[15]);
        assert_eq!(inherited.animation[16],style.animation[16]);
        assert_eq!(inherited.animation[2],style.animation[2]);
        assert_eq!(inherited.animation[17],style.animation[17]);
    }

    #[test]
    fn named_progress_timeline_cascade_and_auto_duration_preserve_component_grammar() {
        let index=StyleIndex::new(Vec::new());
        let style=compute(&element("animation:fade/* boundary */auto both linear;animation-timeline:--track;animation-range:exit;scroll-timeline:--scroll inline;view-timeline:--track;animation-duration:-1s"),None,&index).unwrap();
        assert_eq!(style.animation[0].as_deref(),Some("fade"));
        assert_eq!(style.animation[1].as_deref(),Some("auto"));
        assert_eq!(style.animation[9].as_deref(),Some("--track"));
        assert_eq!(style.animation[10].as_deref(),Some("exit"));
        assert_eq!(style.animation[11].as_deref(),Some("--scroll"));
        assert_eq!(style.animation[12].as_deref(),Some("inline"));
        assert_eq!(style.animation[13].as_deref(),Some("--track"));
        let reset=compute(&element("animation-timeline:--track;animation-range:exit;animation:fade 1s"),None,&index).unwrap();
        assert_eq!(reset.animation[9].as_deref(),Some("auto"));
        assert_eq!(reset.animation[10].as_deref(),Some("normal"));
        assert!(animation_values("scroll-timeline","--track x y").is_none());
        assert!(animation_values("animation-range","exit nonsense").is_none());
    }

    #[test]
    fn specification_embedded_hints_and_preferred_ratios_follow_author_cascade() {
        let index = StyleIndex::new(Vec::new());
        let style = compute(&element("aspect-ratio:auto 3 / 4"), None, &index).unwrap();
        assert_eq!(style.computed_css_value("aspect-ratio", computed_values::ComputedValueContext::default()).as_deref(), Some("auto 3 / 4"));
        assert_eq!(style.preferred_aspect_ratio(Some(2.0)), Some(2.0));
        let plain = compute(&element("aspect-ratio:3 / 4 auto;aspect-ratio:calc(6 / 2) / 4"), None, &index).unwrap();
        assert_eq!(plain.preferred_aspect_ratio(Some(2.0)), Some(0.75));
        let degenerate = compute(&element("aspect-ratio:0 / 0"), None, &index).unwrap();
        assert_eq!(degenerate.aspect_ratio, None);
        assert_eq!(degenerate.preferred_aspect_ratio(Some(2.0)), Some(2.0));
        assert_eq!(degenerate.computed_css_value("aspect-ratio", computed_values::ComputedValueContext::default()).as_deref(), Some("0 / 0"));
        let inherited = compute(&element("aspect-ratio:inherit"), Some(&style), &index).unwrap();
        assert_eq!(inherited.aspect_ratio_components, Some([3.0,4.0]));
        assert!(inherited.aspect_ratio_auto);
        let document = crate::html::parse("<!doctype html><img id=i width='25%' height='40px' hspace='10%' vspace='3' align='center' border='2'><iframe id=f width='0%' frameborder='-0'></iframe><video id=v width='80' height='40' style='height:auto;aspect-ratio:revert'>",64).unwrap();
        let get = |name| crate::selector::get_element_by_id(&document,document.root(),name).unwrap().unwrap();
        let img = compute_node(&document,get("i"),None,&index).unwrap()
            .resolve_percentages_with_query(200.0,None,ContainerUnitContext::default());
        assert_eq!((img.width,img.height),(Some(50.0),Some(40.0)));
        assert_eq!(img.margin_sides,[3.0,20.0,3.0,20.0]);
        assert_eq!(img.vertical_align,VerticalAlign::BaselineMiddle);
        assert_eq!(img.used_border_widths(),[2.0;4]);
        let frame = compute_node(&document,get("f"),None,&index).unwrap();
        assert_eq!(frame.width,Some(0.0));
        assert_eq!(frame.used_border_widths(),[0.0;4]);
        let video = compute_node(&document,get("v"),None,&index).unwrap();
        assert_eq!((video.width,video.height),(Some(80.0),None));
        assert_eq!(video.aspect_ratio_components,None);
    }

    #[test]
    fn specification_font_relative_units_use_final_metrics_root_and_self_reference() {
        struct Metrics;
        impl TextShaper for Metrics {
            fn shape(&self, _: &str, _: f32) -> Result<crate::paint::ShapedRun, ()> { Err(()) }
            fn ascent(&self, size: f32) -> f32 { size * 0.8 }
            fn line_height(&self, size: f32) -> f32 { size * 1.25 }
            fn font_relative_metrics_styled(&self, size: f32, _: &FontSpec) -> FontRelativeMetrics {
                FontRelativeMetrics { ex: size * 0.3, ch: size * 0.6 }
            }
            fn font_unit_metrics_styled(&self, size: f32, font: &FontSpec, vertical: bool, upright_zero: bool) -> crate::paint::FontUnitMetrics {
                let selected = font.families.as_ref().is_some_and(|families| families.iter().any(|family| family.named().is_some_and(|name| name.as_ref() == "Selected")));
                crate::paint::FontUnitMetrics { cap: Some(size * if selected { 0.9 } else { 0.7 }), ch: Some(size * if upright_zero { 1.0 } else { 0.6 }), ic: Some(size * if vertical { 1.1 } else { 1.0 }) }
            }
        }
        let index = StyleIndex::new(Vec::new());
        let compute = |raw: &str, parent: Option<&Style>| compute_for_named(&element(raw), parent, &index, None,
            u64::MAX, Some(&Metrics), None, None, None).unwrap();
        let root = compute("width:2lh;font-size:20px;line-height:2", None);
        assert_eq!(root.width, Some(80.0), "source order cannot precede line-height computation");
        let child = compute("font-size:10px;line-height:1.5;width:2lh;height:2rlh;margin:1rex 1rcap 1rch 1ric", Some(&root));
        assert_eq!((child.width, child.height), (Some(30.0), Some(80.0)));
        assert_eq!(child.margin_sides, [6.0, 14.0, 12.0, 20.0]);
        let self_ref = compute("font-size:1lh;line-height:1lh;width:1cap", Some(&root));
        assert_eq!(self_ref.font_size, 40.0);
        assert_eq!(self_ref.line_height, LineHeight::Pixels(40.0));
        assert_eq!(self_ref.width, Some(28.0));
        let root_self = compute("font-size:1rlh;line-height:1rlh;height:1rlh", None);
        assert_eq!(root_self.font_size, 20.0);
        assert_eq!(root_self.line_height, LineHeight::Pixels(20.0));
        assert_eq!(root_self.height, Some(20.0));
        let inherited = compute("font-size:10px;line-height:inherit;width:inherit;height:1lh", Some(&root));
        assert_eq!((inherited.width, inherited.height), (Some(80.0), Some(20.0)));
        let vertical = compute("font-size:10px;writing-mode:vertical-rl;text-orientation:upright;width:1ch;height:1ic", Some(&root));
        assert_eq!((vertical.width, vertical.height), (Some(10.0), Some(11.0)));
        let mixed = compute("font-size:10px;writing-mode:vertical-rl;text-orientation:mixed;width:1ch;height:1ic", Some(&root));
        assert_eq!((mixed.width, mixed.height), (Some(6.0), Some(11.0)));
        let mut query = compute("font-size:10cqw;line-height:10cqh;width:2lh;height:1cap", None);
        let query_context = ContainerUnitContext { width:ContainerUnitBasis::Size(200.0), height:ContainerUnitBasis::Size(100.0), ..ContainerUnitContext::default() };
        assert!(query.resolve_query_context_with_text(query_context, Some(&Metrics)));
        assert_eq!((query.font_size, query.line_height, query.width, query.height), (20.0, LineHeight::Pixels(10.0), Some(20.0), Some(14.0)));
        let colored = compute("border:1lh solid currentColor;box-shadow:1cap 1lh currentColor;color:rgb(12 34 56);font-size:20px;line-height:2", None);
        assert_eq!(colored.used_border_widths(), [40.0; 4]);
        assert_eq!(colored.border_color, colored.color);
        let shadow = &colored.shadows.as_ref().unwrap()[0];
        assert_eq!((shadow.offset_x, shadow.offset_y, shadow.color), (14.0, 40.0, colored.color));
        let channel = "color:color(srgb calc(.5 + .25 * sign(1cap - 16px)) calc(.5 + .25 * sign(1lh - 30px)) 0)";
        let consumers = "background-color:currentColor;border:1px solid currentColor;column-rule-color:currentColor;outline-color:currentColor;stop-color:currentColor;text-decoration-color:currentColor;box-shadow:1px 2px currentColor";
        let expected = compute("color:color(srgb .75 .75 0)", None).color;
        for source in [alloc::format!("{channel};{consumers};font-size:20px;font-family:Selected;line-height:2"),
            alloc::format!("font-size:20px;font-family:Selected;line-height:2;{consumers};{channel}")] {
            let final_color = compute(&source, None);
            assert_eq!(final_color.color, expected, "foreground channels use selected font and final line-height");
            assert_eq!((final_color.background, final_color.border_color, final_color.svg_stop_color), (expected, expected, expected));
            assert_eq!((final_color.column_rule_color, final_color.outline.color, final_color.text_decoration_color), (Some(expected), Some(expected), Some(expected)));
            assert_eq!(final_color.shadows.as_ref().unwrap()[0].color, expected);
            let inherited_color = compute("font-size:10px;line-height:1;background-color:currentColor", Some(&final_color));
            assert_eq!((inherited_color.color, inherited_color.background), (expected, expected), "inherited computed foreground is not re-evaluated with child metrics");
        }
        let after = compute("height:1rlh;width:1rcap", Some(&query));
        assert_eq!((after.width, after.height), (Some(14.0), Some(10.0)));
    }

    #[test]
    fn specification_font_relative_units_missing_metrics_use_normative_fallbacks() {
        struct Missing;
        impl TextShaper for Missing {
            fn shape(&self, _: &str, _: f32) -> Result<crate::paint::ShapedRun, ()> { Err(()) }
            fn ascent(&self, size: f32) -> f32 { size * 0.75 }
            fn line_height(&self, size: f32) -> f32 { size * 1.5 }
            fn font_unit_metrics_styled(&self, _: f32, _: &FontSpec, _: bool, _: bool) -> crate::paint::FontUnitMetrics { Default::default() }
        }
        let index=StyleIndex::new(Vec::new());
        for (raw, expected) in [("font-size:20px;width:1cap;height:1ic",(15.0,20.0)),
            ("font-size:20px;width:1ch;height:1lh",(10.0,30.0)),
            ("font-size:20px;writing-mode:vertical-rl;text-orientation:upright;width:1ch;height:1ic",(20.0,20.0))] {
            let style=compute_for_named(&element(raw),None,&index,None,u64::MAX,Some(&Missing),None,None,None).unwrap();
            assert_eq!((style.width,style.height),(Some(expected.0),Some(expected.1)));
        }
    }

    #[test]
    fn current_font_query_lengths_rebase_both_pair_axes_and_actual_zero_to_positive_metrics() {
        struct Metrics;
        impl TextShaper for Metrics {
            fn shape(&self,_:&str,_:f32)->Result<crate::paint::ShapedRun,()>{Err(())}
            fn ascent(&self,size:f32)->f32{size*0.8}
            fn line_height(&self,size:f32)->f32{size*1.2}
            fn font_relative_metrics_styled(&self,size:f32,_:&FontSpec)->FontRelativeMetrics {
                FontRelativeMetrics{ex:size*0.3,ch:size*0.7}
            }
        }
        let index=StyleIndex::new(Vec::new());
        let parent=compute(&element("font-size:0"),None,&index).unwrap();
        let mut style=compute(&element("font-size:10cqw;border-spacing:2em 3em;padding:2ex 3ch"),Some(&parent),&index).unwrap();
        assert!(!style.resolve_query_context_with_text(ContainerUnitContext::default(),Some(&Metrics)));
        let query=ContainerUnitContext{width:ContainerUnitBasis::Size(200.0),..ContainerUnitContext::default()};
        assert!(style.resolve_query_context_with_text(query,Some(&Metrics)));
        assert_eq!(style.font_size,20.0);
        assert_eq!(style.border_spacing,[40.0,60.0]);
        assert_eq!(style.padding_sides,[12.0,42.0,12.0,42.0]);
        assert!(!style.has_query_container_dependencies());
    }

    #[test]
    fn specification_border_spacing_uses_both_computed_font_and_query_axes() {
        let index = StyleIndex::new(Vec::new());
        let style = compute(&element("font-size:10px;border-spacing:0em 3em"), None, &index).unwrap();
        assert_eq!(style.border_spacing, [0.0, 30.0]);
        let child = compute(&element("font-size:20px;border-spacing:inherit"), Some(&style), &index).unwrap();
        assert_eq!(child.border_spacing, [0.0, 30.0], "inherit the computed lengths");
        let mut query = compute(&element("border-spacing:2cqw 3cqh"), None, &index).unwrap();
        let context = ContainerUnitContext { width: ContainerUnitBasis::Size(200.0),
            height: ContainerUnitBasis::Size(100.0), ..ContainerUnitContext::default() };
        assert!(query.resolve_query_context(context));
        assert_eq!(query.border_spacing, [4.0, 3.0]);
        for raw in ["-1em 2px", "-1cqw 2px", "-1cqh", "1px 10%", "1px 2px 3px"] {
            assert_eq!(compute(&element(&alloc::format!("border-spacing:7px;border-spacing:{raw}")), None, &index).unwrap().border_spacing, [7.0; 2]);
        }
        assert_eq!(compute(&element("font-size:0;border-spacing:7px;border-spacing:-1em"),None,&index).unwrap().border_spacing,[7.0;2]);
        assert_eq!(compute(&element("border-spacing:-0cqw"),None,&index).unwrap().border_spacing,[0.0;2]);
        let negative = compute(&element("width:7px;width:-1cqw;padding:7px;padding:-1cqh;min-height:7px;min-height:-1em;font-size:0"),None,&index).unwrap();
        assert_eq!(negative.width,Some(7.0));
        assert_eq!(negative.padding_sides,[7.0;4]);
        assert_eq!(negative.min_height,7.0);
    }

    #[test]
    fn specification_text_overflow_typed_grammar_cascade_and_declaration_identity() {
        use super::declaration_block::DeclarationBlock;
        assert_eq!(Style::initial().text_overflow, TextOverflow::Clip);
        assert_eq!(slots("text-overflow"), &[213]);
        let index = StyleIndex::new(Vec::new());
        for (keyword, expected) in [("clip", TextOverflow::Clip), ("ellipsis", TextOverflow::Ellipsis), ("ELLIPSIS", TextOverflow::Ellipsis), (r"e\6c lipsis", TextOverflow::Ellipsis), ("ellipsis/**/", TextOverflow::Ellipsis)] {
            let style = compute(&element(&alloc::format!("text-overflow:{keyword}")), None, &index).unwrap();
            assert_eq!(style.text_overflow, expected);
            assert_eq!(style.computed_css_value("text-overflow", computed_values::ComputedValueContext::default()), Some(expected.as_str().into()));
            let mut block = DeclarationBlock::default();
            assert!(block.set("text-overflow", keyword, true).unwrap());
            assert_eq!(block.value("text-overflow"), Some((expected.as_str().into(), true)));
            assert_eq!(DeclarationBlock::parse(&block.serialize().unwrap()).unwrap().value("text-overflow"), block.value("text-overflow"));
        }
        let parent = compute(&element("text-overflow:ellipsis"), None, &index).unwrap();
        assert_eq!(compute(&element(""), Some(&parent), &index).unwrap().text_overflow, TextOverflow::Clip);
        for keyword in ["inherit", "initial", "unset", "revert", "revert-layer"] {
            for property in ["text-overflow", "all"] {
                let style = compute(&element(&alloc::format!("text-overflow:ellipsis;{property}:{keyword}")), Some(&parent), &index).unwrap();
                assert_eq!(style.text_overflow, if keyword == "inherit" { TextOverflow::Ellipsis } else { TextOverflow::Clip });
            }
        }
        for invalid in ["auto", "none", "fade", "fade(10px)", "ellipsis clip ellipsis", "\"x\" fade", "ell/**/ipsis", "ellipsis junk"] {
            assert!(declarations(&alloc::format!("text-overflow:{invalid}"), 0).unwrap().is_empty());
            let style = compute(&element(&alloc::format!("text-overflow:ellipsis;text-overflow:{invalid}")), None, &index).unwrap();
            assert_eq!(style.text_overflow, TextOverflow::Ellipsis);
        }
        let layered = StyleIndex::new(parse("@layer first,second;@layer first{div{text-overflow:ellipsis}}@layer second{div{text-overflow:clip;text-overflow:revert-layer}}").unwrap());
        assert_eq!(compute(&element(""), None, &layered).unwrap().text_overflow, TextOverflow::Ellipsis);
    }

    #[test]
    fn specification_text_overflow_extended_markers_grammar_and_cascade() {
        use super::declaration_block::DeclarationBlock;
        assert!(Style::initial().extras.is_none(),"normal styles allocate no marker descriptor or extra storage");
        let index = StyleIndex::new(Vec::new());
        for (input,serialized) in [
            ("''","\"\""), ("'marker string'","\"marker string\""),
            (r"'a\22 b'",r#""a\"b""#), (r#""Hi\a Hi""#,r#""Hi\a Hi""#),
            ("CLIP/**/ELLIPSIS","clip ellipsis"), ("ellipsis clip","ellipsis clip"),
            ("clip clip","clip clip"), ("'left' 'right'","\"left\" \"right\""),
            ("'left' ellipsis","\"left\" ellipsis"), ("clip 'right'","clip \"right\""),
        ] {
            let style=compute(&element(&alloc::format!("text-overflow:{input}")),None,&index).unwrap();
            let markers=style.text_overflow_markers.as_ref().expect("only explicit extended syntax owns a shared descriptor");
            assert_eq!(markers.serialize(),serialized);
            assert_eq!(style.computed_css_value("text-overflow",computed_values::ComputedValueContext::default()),Some(serialized.into()));
            let mut block=DeclarationBlock::default();assert!(block.set("text-overflow",input,true).unwrap());
            assert_eq!(block.value("text-overflow"),Some((serialized.into(),true)));
            assert_eq!(DeclarationBlock::parse(&block.serialize().unwrap()).unwrap().value("text-overflow"),block.value("text-overflow"));
            let inherited=compute(&element("text-overflow:inherit"),Some(&style),&index).unwrap();
            assert!(Arc::ptr_eq(markers,inherited.text_overflow_markers.as_ref().unwrap()),"inherited descriptors share marker strings");
            for reset in ["clip","ellipsis","initial","unset","revert","revert-layer"] {
                let reset=compute(&element(&alloc::format!("text-overflow:{input};text-overflow:{reset}")),None,&index).unwrap();
                assert!(reset.text_overflow_markers.is_none(),"reset clears the whole descriptor atomically");
            }
            assert!(compute(&element(""),Some(&style),&index).unwrap().text_overflow_markers.is_none());
            assert!(compute(&element("text-overflow:inherit;all:initial"),Some(&style),&index).unwrap().text_overflow_markers.is_none());
        }
        let mut eof=DeclarationBlock::default();
        assert!(eof.set("text-overflow","'unterminated",false).unwrap());
        assert_eq!(eof.value("text-overflow"),Some(("\"unterminated\"".into(),false)),"EOF completes a valid string marker token");
        for invalid in ["clip fade", "fade ellipsis", "fade(1em)", "'x' 'y' 'z'", "ellipsis,clip", "\"line\nbreak\"", "clip junk"] {
            let mut block=DeclarationBlock::parse("text-overflow:'kept'").unwrap();
            assert!(!block.set("text-overflow",invalid,false).unwrap());
            assert_eq!(block.value("text-overflow"),Some(("\"kept\"".into(),false)));
        }
        let parent=compute(&element("--marker:'variable';text-overflow:var(--marker) clip"),None,&index).unwrap();
        assert_eq!(parent.text_overflow_markers.as_ref().unwrap().serialize(),"\"variable\" clip");
        let layered=StyleIndex::new(parse("@layer a,b;@layer a{div{text-overflow:'from-a' clip}}@layer b{div{text-overflow:ellipsis;text-overflow:revert-layer}}").unwrap());
        assert_eq!(compute(&element(""),None,&layered).unwrap().text_overflow_markers.as_ref().unwrap().serialize(),"\"from-a\" clip");
    }

    #[test]
    fn specification_scroll_behavior_typed_grammar_cascade_and_declaration_identity() {
        let index=StyleIndex::new(Vec::new());
        assert_eq!(Style::initial().scroll_behavior,ScrollBehavior::Auto);
        assert_eq!(slots("scroll-behavior"),&[212]);
        assert!(!inherited_property(212));
        assert!(ALL_PROPERTY_IDS.contains(&212));
        for (keyword,expected) in [("auto",ScrollBehavior::Auto),("smooth",ScrollBehavior::Smooth),("SmOoTh",ScrollBehavior::Smooth),("AUTO",ScrollBehavior::Auto),(r"s\6d ooth",ScrollBehavior::Smooth),("smooth/**/",ScrollBehavior::Smooth)] {
            let style=compute(&element(&alloc::format!("scroll-behavior:{keyword}")),None,&index).unwrap();
            assert_eq!(style.scroll_behavior,expected);
            assert_eq!(style.computed_css_value("scroll-behavior",computed_values::ComputedValueContext::default()),Some(expected.as_str().into()));
            let mut block=DeclarationBlock::default();
            assert!(block.set("scroll-behavior",keyword,true).unwrap());
            assert_eq!(block.value("scroll-behavior"),Some((expected.as_str().into(),true)));
            let serialized=block.serialize().unwrap();
            assert_eq!(DeclarationBlock::parse(&serialized).unwrap().value("scroll-behavior"),block.value("scroll-behavior"));
        }
        let parent=compute(&element("scroll-behavior:smooth"),None,&index).unwrap();
        assert_eq!(compute(&element(""),Some(&parent),&index).unwrap().scroll_behavior,ScrollBehavior::Auto,"scroll behavior is not inherited");
        for keyword in ["inherit","initial","unset","revert","revert-layer"] {
            let expected=if keyword=="inherit"{ScrollBehavior::Smooth}else{ScrollBehavior::Auto};
            for property in ["scroll-behavior","all"] {
                let style=compute(&element(&alloc::format!("scroll-behavior:smooth;{property}:{keyword}")),Some(&parent),&index).unwrap();
                assert_eq!(style.scroll_behavior,expected,"CSS-wide {property}:{keyword}");
            }
        }
        for invalid in ["instant","none","smooth auto","auto smooth","smooth,smooth","0","10px","smooth()","smooth/**/auto","sm/**/ooth"] {
            assert!(declarations(&alloc::format!("scroll-behavior:{invalid}"),0).unwrap().is_empty());
            let style=compute(&element(&alloc::format!("scroll-behavior:smooth;scroll-behavior:{invalid}")),None,&index).unwrap();
            assert_eq!(style.scroll_behavior,ScrollBehavior::Smooth,"invalid declaration leaves earlier valid cascade candidate");
            let mut block=DeclarationBlock::parse("scroll-behavior:smooth").unwrap();
            assert!(!block.set("scroll-behavior",invalid,false).unwrap());
            assert_eq!(block.value("scroll-behavior"),Some(("smooth".into(),false)));
        }
        let layered=StyleIndex::new(parse("@layer first,second;@layer first{div{scroll-behavior:smooth}}@layer second{div{scroll-behavior:auto;scroll-behavior:revert-layer}}").unwrap());
        assert_eq!(compute(&element(""),None,&layered).unwrap().scroll_behavior,ScrollBehavior::Smooth,"revert-layer reveals earlier layer");
        let important=compute(&element("scroll-behavior:smooth!important;scroll-behavior:auto"),None,&index).unwrap();
        assert_eq!(important.scroll_behavior,ScrollBehavior::Smooth);
    }

    #[test]
    fn specification_unicode_bidi_cascade_ua_scopes_and_all_exclusion() {
        let index=StyleIndex::new(Vec::new());
        for (value,expected) in [("normal",UnicodeBidi::Normal),("embed",UnicodeBidi::Embed),("isolate",UnicodeBidi::Isolate),("bidi-override",UnicodeBidi::BidiOverride),("isolate-override",UnicodeBidi::IsolateOverride),("plaintext",UnicodeBidi::Plaintext)] {
            let style=compute(&element(&alloc::format!("unicode-bidi:{value}")),None,&index).unwrap();assert_eq!(style.unicode_bidi,expected);
            assert_eq!(style.computed_css_value("unicode-bidi",computed_values::ComputedValueContext::default()),Some(value.into()));
        }
        let parent=compute(&element("unicode-bidi:isolate;direction:rtl"),None,&index).unwrap();
        assert_eq!(compute(&element(""),Some(&parent),&index).unwrap().unicode_bidi,UnicodeBidi::Normal);
        assert_eq!(compute(&element("unicode-bidi:inherit"),Some(&parent),&index).unwrap().unicode_bidi,UnicodeBidi::Isolate);
        let all=compute(&element("unicode-bidi:embed;all:initial"),Some(&parent),&index).unwrap();assert_eq!(all.unicode_bidi,UnicodeBidi::Embed);assert_eq!(all.direction,Direction::Rtl);
        let document=crate::html::parse("<span id=a dir=auto>אב</span><bdi id=b>אב</bdi><bdo id=c dir=rtl>abc</bdo><pre id=d dir=auto>אב</pre><span id=e dir=rtl style='unicode-bidi:normal'>אב</span>",64).unwrap();
        for (id,expected) in [("a",UnicodeBidi::Isolate),("b",UnicodeBidi::Isolate),("c",UnicodeBidi::IsolateOverride),("d",UnicodeBidi::Plaintext),("e",UnicodeBidi::Normal)] {
            let node=crate::selector::query_selector(&document,document.root(),&alloc::format!("#{id}")).unwrap().unwrap();assert_eq!(compute_node(&document,node,None,&index).unwrap().unicode_bidi,expected);
        }
    }

    #[test]
    fn specification_modern_text_transform_cascade_canonical_grammar_and_math_defaults() {
        let index=StyleIndex::new(Vec::new());
        let parent=compute(&element("text-transform:full-size-kana uppercase full-width"),None,&index).unwrap();
        assert_eq!(parent.computed_css_value("text-transform",computed_values::ComputedValueContext::default()).unwrap(),"uppercase full-width full-size-kana");
        assert_eq!(compute(&element("text-transform:inherit"),Some(&parent),&index).unwrap().text_transform,parent.text_transform);
        assert_eq!(compute(&element("all:initial"),Some(&parent),&index).unwrap().text_transform,TextTransform::None);
        for invalid in ["none full-width","uppercase lowercase","full-width full-width","math-auto full-size-kana"] {
            assert_eq!(compute(&element(&alloc::format!("text-transform:capitalize;text-transform:{invalid}")),None,&index).unwrap().text_transform,TextTransform::Capitalize);
        }
        let mut declaration=DeclarationBlock::default();
        assert!(declaration.set("text-transform","full-size-kana lowercase full-width",false).unwrap());
        assert_eq!(declaration.value("text-transform"),Some(("lowercase full-width full-size-kana".into(),false)));
        let document=crate::html::parse("<math><mi id=auto>x</mi><mi id=normal mathvariant=normal>x</mi><mi id=author mathvariant=normal style='text-transform:math-auto'>x</mi></math>",64).unwrap();
        for (id,expected) in [("auto",TextTransform::MathAuto),("normal",TextTransform::None),("author",TextTransform::MathAuto)] {
            let node=crate::selector::query_selector(&document,document.root(),&alloc::format!("#{id}")).unwrap().unwrap();
            assert_eq!(compute_node(&document,node,None,&index).unwrap().text_transform,expected);
        }
    }

    #[test]
    fn text_transform_inherits_resets_and_serializes_through_shared_registry() {
        let index=StyleIndex::new(Vec::new());
        let ordinary=compute(&element(""),None,&index).unwrap();
        assert_eq!(ordinary.text_transform,TextTransform::None);
        assert!(ordinary.extras.is_none());
        let parent=compute(&element("text-transform:UPPERCASE"),None,&index).unwrap();
        let child=compute(&element("font:16px serif"),Some(&parent),&index).unwrap();
        assert_eq!(child.text_transform,TextTransform::Uppercase);
        assert_eq!(child.computed_css_value("text-transform",computed_values::ComputedValueContext::default()).unwrap(),"uppercase");
        assert_eq!(compute(&element("text-transform:initial"),Some(&parent),&index).unwrap().text_transform,TextTransform::None);
        assert_eq!(compute(&element("text-transform:unset"),Some(&parent),&index).unwrap().text_transform,TextTransform::Uppercase);
        assert_eq!(compute(&element("all:initial"),Some(&parent),&index).unwrap().text_transform,TextTransform::None);
        let block=DeclarationBlock::parse("text-transform:uppercase!important;text-transform:lowercase").unwrap();
        assert_eq!(block.value("text-transform"),Some(("uppercase".into(),true)));
        for value in ["upper","uppercase lowercase","capitalize none","1px"] {
            assert!(declarations(&alloc::format!("text-transform:{value}"),0).unwrap().is_empty(),"{value}");
        }
    }

    #[test]
    fn imported_occurrence_map_moves_duplicate_graphs_exactly_and_rolls_back_atomically() {
        let text = "@import 'dup.css'; @import 'dup.css';";
        let mut source = StylesheetSource {disabled:false,
            url: Arc::from("https://example.test/root.css"), text: Arc::from(text),
            imports: imports(text).unwrap().into_iter().zip([".box{width:17px}", ".box{width:19px}"]).map(|(rule, text)| LoadedImport {
                rule, source: Some(alloc::boxed::Box::new(StylesheetSource {disabled:false,  url: Arc::from("https://example.test/dup.css"), text: Arc::from(text), imports: Vec::new() })),
            }).collect(),
        };
        let first = source.imports[0].source.as_deref().unwrap() as *const StylesheetSource;
        let second = source.imports[1].source.as_deref().unwrap() as *const StylesheetSource;
        let inserted = "@import 'dup.css'; @import 'dup.css'; @import 'dup.css';";
        let edit = prepare_stylesheet_text_edit_with_import_map(&mut source, Arc::from(inserted), Some(&[None, Some(0), Some(1)])).unwrap();
        assert!(source.imports[0].source.is_none());
        assert_eq!(source.imports[1].source.as_deref().unwrap() as *const StylesheetSource, first);
        assert_eq!(source.imports[2].source.as_deref().unwrap() as *const StylesheetSource, second);
        edit.rollback(&mut source);
        assert_eq!(source.text.as_ref(), text);
        assert_eq!(source.imports[0].source.as_deref().unwrap() as *const StylesheetSource, first);
        assert_eq!(source.imports[1].source.as_deref().unwrap() as *const StylesheetSource, second);
        assert!(prepare_stylesheet_text_edit_with_import_map(&mut source, Arc::from(text), Some(&[Some(0), Some(0)])).is_err());
        assert!(prepare_stylesheet_text_edit_with_import_map(&mut source, Arc::from("@import 'other.css';"), Some(&[Some(1)])).is_err());
        assert_eq!(source.text.as_ref(), text);
        let edit = prepare_stylesheet_text_edit_with_import_map(&mut source, Arc::from("@import 'dup.css';"), Some(&[Some(1)])).unwrap();
        assert_eq!(source.imports[0].source.as_deref().unwrap() as *const StylesheetSource, second);
        edit.rollback(&mut source);
        assert_eq!(source.imports[0].source.as_deref().unwrap() as *const StylesheetSource, first);
    }

