    #[test]
    fn font_size_adjust_cascades_and_resets_with_the_font_shorthand() {
        assert_eq!(
            font_size_adjust("CAP-HEIGHT FROM-FONT"),
            Some(Some(FontSizeAdjust {
                metric: FontMetric::CapHeight,
                value: FontSizeAdjustValue::FromFont,
            }))
        );
        assert_eq!(
            font_size_adjust("0.5"),
            Some(Some(FontSizeAdjust {
                metric: FontMetric::ExHeight,
                value: FontSizeAdjustValue::Number(0.5),
            }))
        );
        assert_eq!(
            font_size_adjust("cap-height calc(0.5 + 1)"),
            Some(Some(FontSizeAdjust {
                metric: FontMetric::CapHeight,
                value: FontSizeAdjustValue::Number(1.5),
            }))
        );
        assert_eq!(
            font_size_adjust("calc(-0.5)"),
            Some(Some(FontSizeAdjust {
                metric: FontMetric::ExHeight,
                value: FontSizeAdjustValue::Number(0.0),
            }))
        );
        assert_eq!(font_size_adjust("none"), Some(None));
        for invalid in ["-0.1", "NaN", "ex-height 0.5 extra", "not-a-metric 0.5"] {
            assert_eq!(font_size_adjust(invalid), None, "{invalid}");
        }

        let index = StyleIndex::new(Vec::new());
        let parent = compute(
            &element("font-size:20px;font-size-adjust:ch-width 0.55;line-height:1"),
            None,
            &index,
        )
        .unwrap();
        assert_eq!(parent.font_size, 20.0);
        assert_eq!(parent.line_height, LineHeight::Number(1.0));
        assert_eq!(
            parent.font_spec().size_adjust,
            Some(FontSizeAdjust {
                metric: FontMetric::ChWidth,
                value: FontSizeAdjustValue::Number(0.55),
            })
        );
        let inherited = compute(&element(""), Some(&parent), &index).unwrap();
        assert_eq!(
            inherited.font_spec().size_adjust,
            parent.font_spec().size_adjust
        );

        let reset = compute(
            &element("font:ITALIC BOLDER CONDENSED 16px serif"),
            Some(&parent),
            &index,
        )
        .unwrap();
        assert_eq!(reset.font.weight, 700);
        assert_eq!(reset.font.stretch, 75.0);
        assert_eq!(reset.font.style, FontStyle::Italic);
        assert_eq!(reset.font_spec().size_adjust, None);
        assert_eq!(
            parse_font_shorthand("lighter 16px serif").unwrap().weight,
            100
        );
        assert!(parse_font_shorthand("16px/var(--line-height) serif").is_none());
    }

    #[test]
    fn specification_font_size_adjust_source_and_first_available_metric_freeze_before_inheritance() {
        for (raw, expected) in [("ex-height 0.5", "0.5"), ("ex-height from-font", "from-font"),
            ("ex-height calc(0.5)", "calc(0.5)"), ("cap-height calc(0.5 + 1)", "cap-height calc(1.5)"),
            ("cap-height calc(10 + (sign(20cqw - 10px) * 5))", "cap-height calc(10 + (5 * sign(20cqw - 10px)))")] {
            let declaration = DeclarationBlock::parse(&alloc::format!("font-size-adjust:{raw}")).unwrap();
            assert_eq!(declaration.value("font-size-adjust").unwrap().0, expected);
            assert_eq!(serialize_cssom_property_value("font-size-adjust", raw).as_deref(), Some(expected));
        }
        struct Metrics;
        impl TextShaper for Metrics {
            fn shape(&self, _: &str, _: f32) -> Result<crate::paint::ShapedRun, ()> {
                Ok(crate::paint::ShapedRun { glyphs: Arc::from([]), width: 0.0 })
            }
            fn ascent(&self, size: f32) -> f32 { size }
            fn line_height(&self, size: f32) -> f32 { size }
            fn first_available_font_metric(&self, font: &FontSpec, metric: FontMetric) -> Option<Option<f32>> {
                Some((metric != FontMetric::IcHeight).then_some(if font.weight == 700 { 0.8 } else { 0.5 }))
            }
        }
        let index = StyleIndex::new(Vec::new());
        let parent = compute_for(&element("font-size-adjust:from-font"), None, &index, None, u64::MAX, Some(&Metrics), None).unwrap();
        assert_eq!(parent.font.size_adjust.unwrap().value, FontSizeAdjustValue::Number(0.5));
        let inherited = compute_for(&element("font-weight:700"), Some(&parent), &index, None, u64::MAX, Some(&Metrics), None).unwrap();
        assert_eq!(inherited.font.size_adjust.unwrap().value, FontSizeAdjustValue::Number(0.5), "inherit the computed metric, not the child's different font ratio");
        let explicit = compute_for(&element("font-weight:700;font-size-adjust:from-font"), Some(&parent), &index, None, u64::MAX, Some(&Metrics), None).unwrap();
        assert_eq!(explicit.font.size_adjust.unwrap().value, FontSizeAdjustValue::Number(0.8));
        let missing = compute_for(&element("font-size-adjust:ic-height from-font"), None, &index, None, u64::MAX, Some(&Metrics), None).unwrap();
        assert!(missing.font.size_adjust.is_none(), "a genuinely absent metric computes to none");
        let mut pending = compute(&element("font-size-adjust:from-font"), None, &index).unwrap();
        assert_eq!(pending.font.size_adjust.unwrap().value, FontSizeAdjustValue::FromFont, "no authority stays unresolved");
        assert!(pending.resolve_query_context_with_text(ContainerUnitContext::no_container(index.environment), Some(&Metrics)));
        assert_eq!(pending.font.size_adjust.unwrap().value, FontSizeAdjustValue::Number(0.5));
    }

    #[test]
    fn specification_font_size_adjust_math_uses_parent_metrics_and_retains_unknown_queries() {
        let index = StyleIndex::new(Vec::new());
        let parent = compute(&element("font-size:30px"), None, &index).unwrap();
        for own in [0, 10, 60] {
            let child = compute(&element(&alloc::format!("font-size:{own}px;font-size-adjust:cap-height calc(1 * tan(atan2(1em, 1px)))")), Some(&parent), &index).unwrap();
            let Some(FontSizeAdjust { metric: FontMetric::CapHeight, value: FontSizeAdjustValue::Number(value) }) = child.font.size_adjust else { panic!("contextual adjustment must remain admitted"); };
            assert!((value - 30.0).abs() < 0.001, "font-affecting math resolves against the actual parent");
            assert!(child.relative_expressions.is_empty(), "computed absolute results retain no metadata");
            let inherited = compute(&element("font-size:100px"), Some(&child), &index).unwrap();
            assert_eq!(inherited.font.size_adjust, child.font.size_adjust);
            let reset = compute(&element("font:16px serif"), Some(&child), &index).unwrap();
            assert_eq!(reset.font.size_adjust, None);
        }
        let mut pending = compute(&element("font-size-adjust:ch-width calc(5 + sign(2cqw - 10px))"), Some(&parent), &index).unwrap();
        assert!(pending.property_query_context_pending("font-size-adjust"));
        assert!(pending.font_query_context_pending());
        assert!(!pending.resolve_query_context(ContainerUnitContext::default()));
        let query = ContainerUnitContext { width: ContainerUnitBasis::Size(100.0), height: ContainerUnitBasis::Size(200.0), ..ContainerUnitContext::default() };
        assert!(pending.resolve_query_context(query));
        assert_eq!(pending.font.size_adjust, Some(FontSizeAdjust { metric: FontMetric::ChWidth, value: FontSizeAdjustValue::Number(4.0) }));
        assert!(!pending.font_query_context_pending());
        let mut unresolved_parent = compute(&element("font-size:20cqw"), None, &index).unwrap();
        let source = element("font-size-adjust:cap-height calc(1 * tan(atan2(1em, 1px)))");
        let mut child = compute(&source, Some(&unresolved_parent), &index).unwrap();
        assert!(child.font_query_context_pending(), "unknown parent metrics cannot be replaced by a static font");
        assert!(!child.resolve_query_context(query), "the declaring ancestor must resolve before inheritance");
        assert!(unresolved_parent.resolve_query_context(query));
        let child = compute(&source, Some(&unresolved_parent), &index).unwrap();
        let Some(FontSizeAdjust { value: FontSizeAdjustValue::Number(value), .. }) = child.font.size_adjust else { panic!("resolved parent supplies font math"); };
        assert!((value - 20.0).abs() < 0.001);
        for invalid in ["cap-height calc(1em)", "calc(5%)", "-1"] { assert!(!supports_property_value("font-size-adjust", invalid), "{invalid}"); }
    }

    #[test]
    fn font_face_matching_uses_descriptor_rank_before_unicode_ranges() {
        fn source(faces: &[FontFaceRule], index: usize) -> &str {
            match &faces[index].sources[0] {
                FontFaceSource::Url(source) => source,
                FontFaceSource::Local(_) => "local",
            }
        }

        let mut groups = [parse_stylesheet(
            "@layer base, override; \
             @layer base { @font-face { font-family: Shared; src: url(base.woff); unicode-range: U+0041-0042 } } \
             @layer override { @font-face { font-family: Shared; src: url(override.woff); unicode-range: U+0042 } } \
             @font-face { font-family: Shared; src: url(bold.woff); font-weight: 700; unicode-range: U+0042 }",
        )
        .unwrap()];
        let faces = canonicalize_font_faces(&mut groups);
        let spec = parse_font_shorthand("normal 16px Shared").unwrap();

        let a = matching_font_faces(&spec, &faces, "A");
        assert_eq!(a.len(), 1);
        assert_eq!(source(&faces, a[0]), "base.woff");

        let b = matching_font_faces(&spec, &faces, "B");
        assert_eq!(
            b.iter()
                .map(|&index| source(&faces, index))
                .collect::<Vec<_>>(),
            ["override.woff", "base.woff"]
        );
        assert!(!b.iter().any(|&index| source(&faces, index) == "bold.woff"));
        assert!(matching_font_faces(&spec, &faces, "").is_empty());
    }

    #[test]
    fn rendering_font_faces_preserve_pending_primary_and_observed_coverage() {
        let mut groups = [parse_stylesheet(
            "@font-face { font-family: Primary; src: url(primary.woff); unicode-range: U+0041 } \
             @font-face { font-family: Secondary; src: url(secondary.woff); unicode-range: U+0041, U+1F600 } \
             @font-face { font-family: Unused; src: url(unused.woff) }",
        )
        .unwrap()];
        let faces = canonicalize_font_faces(&mut groups);
        let spec = parse_font_shorthand("16px Primary, Secondary, Unused").unwrap();
        let mut observed = Vec::new();
        let selected = rendering_font_faces(&spec, &faces, "AA😀", |face, piece| {
            observed.push((face.family.to_string(), piece.to_owned()));
            true // A pending primary is not a reason to demand its fallback.
        });
        assert_eq!(selected, [0, 1]);
        assert_eq!(
            observed,
            [
                ("Primary".into(), "A".into()),
                ("Primary".into(), "A".into()),
                ("Secondary".into(), "😀".into()),
            ]
        );

        let selected = rendering_font_faces(&spec, &faces, "A", |face, _| {
            face.family.as_ref() != "Primary" // Failed source or missing glyph.
        });
        assert_eq!(selected, [1]);
        assert!(rendering_font_faces(&spec, &faces, "", |_, _| {
            panic!("empty text must not query sources")
        })
        .is_empty());
        assert!(rendering_font_faces(&spec, &faces, "A", |_, _| false).is_empty());
    }

