    #[test]
    fn subgrid_name_only_repeat_retains_empty_groups_and_cascades_atomically() {
        let index = StyleIndex::new(Vec::new());
        let style = compute(&element("grid-template-columns:subgrid [a] [] repeat(auto-fill,[b][]) [c]; grid-template-rows:subgrid repeat(2,[x][]) []"), None, &index).unwrap();
        let columns = style.grid_columns_subgrid_repeat.as_ref().unwrap();
        assert_eq!(
            (
                columns.prefix_lines,
                columns.repeat_lines,
                columns.suffix_lines
            ),
            (2, 2, 1)
        );
        assert_eq!(columns.prefix_names[0].line, 0);
        assert_eq!(columns.repeat_names[0].name.as_ref(), "b");
        assert_eq!(columns.suffix_names[0].line, 0);
        assert!(style.grid_column_names.is_none());
        let rows = style.grid_rows_subgrid_repeat.as_ref().unwrap();
        assert_eq!(
            (rows.prefix_lines, rows.repeat_lines, rows.suffix_lines),
            (5, 0, 0)
        );
        assert_eq!(style.grid_row_names.as_ref().unwrap()[1].line, 2);
        assert!(Arc::ptr_eq(
            style.grid_row_names.as_ref().unwrap(),
            &rows.prefix_names
        ));
        let inherited = compute(
            &element("grid-template-columns:inherit;grid-template-rows:inherit"),
            Some(&style),
            &index,
        )
        .unwrap();
        assert_eq!(
            inherited.grid_columns_subgrid_repeat,
            style.grid_columns_subgrid_repeat
        );
        assert_eq!(
            inherited.grid_rows_subgrid_repeat,
            style.grid_rows_subgrid_repeat
        );
        let reset = compute(
            &element("grid-template-columns:none;grid-template-rows:initial"),
            Some(&style),
            &index,
        )
        .unwrap();
        assert!(!reset.grid_columns_subgrid && !reset.grid_rows_subgrid);
        assert!(
            reset.grid_columns_subgrid_repeat.is_none() && reset.grid_rows_subgrid_repeat.is_none()
        );
        for invalid in [
            "subgrid repeat(auto-fit,[a])",
            "subgrid repeat(auto-fill,20px)",
            "subgrid repeat(auto-fill,[a]) repeat(auto-fill,[b])",
            "subgrid repeat(66,[])",
        ] {
            assert!(
                grid_template(invalid, static_length_context()).is_none(),
                "{invalid}"
            );
        }
    }

    #[test]
    fn font_stretch_cascades_inherits_and_resets_with_shorthand() {
        let index = StyleIndex::new(Vec::new());
        let parent = compute(&element("font-stretch:semi-condensed"), None, &index).unwrap();
        assert_eq!(parent.font.stretch, 87.5);
        assert_eq!(
            compute(&element("font-stretch:CONDENSED"), None, &index)
                .unwrap()
                .font
                .stretch,
            75.0
        );
        let child = compute(
            &element("font-stretch:0%;font-stretch:-10%"),
            Some(&parent),
            &index,
        )
        .unwrap();
        assert_eq!(child.font.stretch, 0.0);
        let child = compute(&element("font-stretch:123.5%"), Some(&parent), &index).unwrap();
        assert_eq!(child.font.stretch, 123.5);
        let reset = compute(&element("font:italic 16px serif"), Some(&parent), &index).unwrap();
        assert_eq!(reset.font.stretch, 100.0);
        let expanded = compute(&element("font:expanded bold 16px serif"), None, &index).unwrap();
        assert_eq!(expanded.font.stretch, 125.0);
        let faces = parse_font_faces(r#"@MEDIA screen { @FONT-FACE { font-family:"A" /* family */;src:url("a/*literal*/.woff");font-weight:700/*weight*/;font-stretch:CONDENSED;ascent-override:80%;descent-override:20%;ascent-override:-10%; } }"#).unwrap();
        assert_eq!(faces.len(), 1);
        assert_eq!(&*faces[0].family, "A");
        assert_eq!(faces[0].weight, 700);
        assert_eq!(faces[0].stretch, 75.0);
        assert_eq!(faces[0].ascent_override, Some(0.8));
        assert_eq!(faces[0].descent_override, Some(0.2));
        assert_eq!(
            faces[0].sources.as_ref(),
            &[FontFaceSource::Url("a/*literal*/.woff".into())]
        );
        assert_eq!(&*faces[0].media[0], "screen");
    }

