    #[test]
    fn identifiers_decode_css_escapes() {
        assert_eq!(
            parse_selector(r"#\31 23", 0).unwrap().id.as_deref(),
            Some("123")
        );
        assert_eq!(parse_selector(r".a\+b", 0).unwrap().classes, ["a+b"]);
        assert_eq!(parse_selector(r".a\ ", 0).unwrap().classes, ["a "]);
        assert!(parse_selector(".-", 0).is_err());
        assert_eq!(
            parse_selector(".caf\u{e9}", 0).unwrap().classes,
            ["caf\u{e9}"]
        );
        assert_eq!(parse_selector(r".\0", 0).unwrap().classes, ["\u{fffd}"]);
        assert!(parse_selector(".bad\\", 0).is_err());
        assert!(parse_selector(".bad\\\nname", 0).is_err());
        assert_eq!(
            parse_selector(r".\61 > p", 0).unwrap().specificity,
            (0, 1, 1)
        );
    }

    #[test]
    fn parses_common_alpha_colors() {
        assert_eq!(
            color("#1234").unwrap(),
            Rgba {
                r: 17,
                g: 34,
                b: 51,
                a: 68
            }
        );
        assert_eq!(color("#10203080").unwrap().a, 128);
        assert_eq!(color("rgba(16, 32, 48, 0.5)").unwrap().a, 128);
        assert_eq!(
            color("rgba(100%, 0%, 0%, 0.5)").unwrap(),
            Rgba {
                r: 255,
                g: 0,
                b: 0,
                a: 128
            }
        );
        assert_eq!(color("rgb(16, 32, 48)").unwrap().b, 48);
        assert_eq!(
            color("RGB(100% 0% 0% / 50%)").unwrap(),
            Rgba {
                r: 255,
                g: 0,
                b: 0,
                a: 128
            }
        );
        assert_eq!(
            color("hsl(0.5turn 100% 50%)").unwrap(),
            Rgba {
                r: 0,
                g: 255,
                b: 255,
                a: 255
            }
        );
        assert_eq!(
            color("hwb(120 20% 10%)").unwrap(),
            Rgba {
                r: 51,
                g: 230,
                b: 51,
                a: 255
            }
        );
        assert_eq!(
            color("color(srgb 1 0 0)").unwrap(),
            Rgba {
                r: 255,
                g: 0,
                b: 0,
                a: 255
            }
        );
        assert_eq!(color("color(srgb-linear 0 1 0)").unwrap().g, 255);
        assert!(color("lab(52.2345 40.1645 59.9971)").is_some());
        assert!(color("lch(52.2345 72.2 56.2)").is_some());
        assert!(color("oklab(0.65125 -0.0320 0.1274)").is_some());
        assert!(color("oklch(0.452 0.313 264.1)").is_some());
        assert_eq!(
            background_shorthand("lab(52.2345 40.1645 59.9971)")
                .unwrap()
                .color.and_then(|value| if let Value::Background(color)=value {Some(color)} else {None}),
            color("lab(52.2345 40.1645 59.9971)")
        );
        assert!(color("color(display-p3 0.4 0.2 0.9)").is_some());
        assert!(color("color(a98-rgb 0.44091 0.49971 0.37408)").is_some());
        assert!(color("color(prophoto-rgb 0.36589 0.41717 0.31333)").is_some());
        assert!(color("color(rec2020 0.6295 0.9657 0.3633)").is_some());
        assert!(background_shorthand("oklab(0.65125 -0.0320 0.1274)").is_some());
        assert_eq!(
            color("rebeccapurple").unwrap(),
            Rgba {
                r: 102,
                g: 51,
                b: 153,
                a: 255
            }
        );
        assert_eq!(
            color("CanvasText").unwrap(),
            Rgba {
                r: 0,
                g: 0,
                b: 0,
                a: 255
            }
        );
        assert_eq!(
            color("color-mix(in srgb, red, blue)").unwrap(),
            Rgba {
                r: 128,
                g: 0,
                b: 128,
                a: 255
            }
        );
        assert_eq!(
            color("color-mix(in srgb, red 75%, blue 75%)").unwrap(),
            Rgba {
                r: 128,
                g: 0,
                b: 128,
                a: 255
            }
        );
        assert_eq!(
            color("color-mix(in hsl shorter hue, hsl(120 100% 50%), hsl(240 100% 50%))").unwrap(),
            Rgba {
                r: 0,
                g: 255,
                b: 255,
                a: 255
            }
        );
        assert_eq!(
            color("color-mix(in hsl longer hue, hsl(120 100% 50%), hsl(240 100% 50%))").unwrap(),
            Rgba {
                r: 255,
                g: 0,
                b: 0,
                a: 255
            }
        );
        assert!(color("color-mix(in oklab, white, black)").is_some());
        assert!(color("color-mix(in lch longer hue, lch(50 60 40), lch(50 60 280))").is_some());
        assert!(color("color-mix(in hwb, red, yellow)").is_some());
        assert_eq!(
            color("rgb(from red r g b)").unwrap(),
            Rgba {
                r: 255,
                g: 0,
                b: 0,
                a: 255
            }
        );
        assert_eq!(
            color("rgb(from rgb(255 128 0) calc(r/2) g b)").unwrap(),
            Rgba {
                r: 128,
                g: 128,
                b: 0,
                a: 255
            }
        );
    }

    #[test]
    fn flex_shorthand_preserves_math_components_and_clamps_calculated_factors() {
        let kind = |raw: &str| NodeKind::Element {
            namespace: Namespace::Html,
            name: "div".into(),
            attributes: alloc::vec![("style".into(), raw.into())],
        };
        let index = StyleIndex::new(Vec::new());
        let style = compute(&kind("flex:calc(1) calc(2 + 1) calc(3px)"), None, &index).unwrap();
        assert_eq!(
            (style.flex_grow, style.flex_shrink, style.flex_basis),
            (1.0, 3.0, Some(3.0))
        );
        let style = compute(&kind("flex:calc(-1) calc(-1) 0"), None, &index).unwrap();
        assert_eq!(
            (style.flex_grow, style.flex_shrink, style.flex_basis),
            (0.0, 0.0, Some(0.0))
        );
        assert!(!supports_declaration("flex", "-1 1 0"));
        assert!(!supports_declaration("flex-grow", "-1"));
        assert!(supports_declaration("flex-grow", "calc(-1)"));
    }

    #[test]
    fn specification_background_shorthand_preserves_color_layers_and_atomic_grammar() {
        let index=StyleIndex::new(Vec::new());
        for color in ["red","blue"] {
            let style=compute(&element(&alloc::format!("color:{color};background:linear-gradient(transparent,transparent) 0/10px 20px no-repeat, none CURRENTCOLOR")),None,&index).unwrap();
            assert_eq!(style.background,style.color);
            let layers=style.background_images.as_ref().unwrap();assert_eq!(layers.len(),2);
            let size=style.background_size.as_ref().unwrap()[0];
            assert_eq!(size.width.unwrap().pixels,10.0);assert_eq!(size.height.unwrap().pixels,20.0);
            assert_eq!(style.background_repeat.as_ref().unwrap()[0],[BackgroundRepeat::NoRepeat;2]);
        }
        let style=compute(&element("color:red;background:rgb(from currentcolor r g b)"),None,&index).unwrap();assert_eq!(style.background,style.color);
        let style=compute(&element("background:none content-box, none border-box red"),None,&index).unwrap();
        assert_eq!(style.background_images.as_ref().unwrap().len(),2,"none is still a real background layer");
        assert_eq!(style.background_clip.as_ref().unwrap().as_ref(),[BackgroundBox::Content,BackgroundBox::Border]);
        for valid in ["0/10px 20px no-repeat red","center / auto auto red","0 / cover red","0/contain green","left top/20px 30px padding-box border-box blue"] {assert!(background_shorthand(valid).is_some(),"{valid}");}
        let mut block=DeclarationBlock::parse("background:blue url(old.png) 10px 20px / 30px 40px no-repeat fixed padding-box border-box!important").unwrap();
        let before=block.serialize().unwrap();
        for invalid in ["none none","none url(new.png)","url(new.png) none","repeat repeat-x red","repeat url(new.png) no-repeat","center/ red","center/","0/cover auto","0/10px 20px 30px","red, none","padding-box url(new.png) border-box","red blue"] {
            assert!(background_shorthand(invalid).is_none(),"{invalid}");block.set("background",invalid,false).unwrap();assert_eq!(block.serialize().unwrap(),before,"invalid shorthand must not reset any longhand: {invalid}");
        }
        block.set("background","CURRENTCOLOR",false).unwrap();assert_eq!(block.value("background-color"),Some(("currentcolor".into(),false)));
        assert_eq!(block.value("background-image"),Some(("none".into(),false)));
        assert_eq!(block.value("background-size"),Some(("auto".into(),false)));
        block.set("background","rgb(from currentcolor r g b)",true).unwrap();assert_eq!(block.value("background-color"),Some(("rgb(from currentcolor r g b)".into(),true)));
        let serialized=block.serialize().unwrap();let reparsed=DeclarationBlock::parse(&serialized).unwrap();assert_eq!(reparsed.value("background-color"),block.value("background-color"));
        block.set("background","var(--paint)",false).unwrap();assert_eq!(block.value("background"),Some(("var(--paint)".into(),false)));
    }

    #[test]
    fn background_position_axes_and_size_runs_follow_author_grammar() {
        let position =
            background_position(&["center", "right", "7%"], static_length_context()).unwrap();
        assert!((position[0].fraction - 0.93).abs() < 0.001);
        assert_eq!(position[1].fraction, 0.5);
        assert!(background_shorthand("black 0 url(https://example.invalid/) / cover").is_none());
        assert!(background_shorthand("black url(https://example.invalid/) 0 / cover").is_some());
        assert!(background_shorthand("calc(10px + 5%) center / cover black").is_some());
    }

    #[test]
    fn contextual_and_relative_colors_resolve_after_inherited_color() {
        let parent = Style {
            color: Rgba {
                r: 255,
                g: 0,
                b: 0,
                a: 128,
            },
            ..Style::initial()
        };
        let kind = NodeKind::Element {
            namespace: Namespace::Html, name: "div".into(),
            attributes: alloc::vec![("style".into(),
                "color:rgb(from currentcolor calc(r / 2) g b / alpha);background-color:alpha(from currentcolor / 25%);border-color:currentcolor blue".into())],
        };
        let style = compute(&kind, Some(&parent), &StyleIndex::new(Vec::new())).unwrap();
        assert_eq!(
            style.color,
            Rgba {
                r: 128,
                g: 0,
                b: 0,
                a: 128
            }
        );
        assert_eq!(
            style.background,
            Rgba {
                r: 128,
                g: 0,
                b: 0,
                a: 64
            }
        );
        assert_eq!(style.border_color, style.color);
        assert_eq!(color("hsl(from red 120 s l)"), color("lime"));
        assert_eq!(color("alpha(from blue)"), color("blue"));
        assert_eq!(color("light-dark(red, blue)"), color("red"));
        assert_eq!(color("contrast-color(white)"), color("black"));
        assert_eq!(color("hwb(from red 120 w b / alpha)"), color("lime"));
        assert_eq!(
            color("color(srgb calc(1 / 2) 50% 0 / 25%)"),
            Some(Rgba {
                r: 128,
                g: 128,
                b: 0,
                a: 64
            })
        );
        assert_eq!(
            color("color-mix(red, blue)"),
            color("color-mix(in oklab, red, blue)")
        );
        assert!(color("contrast-color(color-mix(blue, green))").is_some());
        assert_eq!(color("color(srgb NaN 0 0)"), None);
        assert_eq!(color("color(srgb 0px 0 0)"), None);
        for value in [-2.0, -0.5, -0.01, 0.0, 0.01, 0.5, 2.0] {
            assert!((linear_to_srgb(srgb_to_linear(value)) - value).abs() < 0.00001);
        }
        assert_eq!(color("color(display-p3 -1 -1 -1)"), color("black"));
        assert_eq!(color("color(a98-rgb -1 -1 -1)"), color("black"));
        for invalid in [
            "rgb(10%, 20, 30)",
            "rgb(NaN 0 0)",
            "lab(inf 0 0)",
            "hsl(from red 50% s l)",
            "alpha(from red / NaN)",
        ] {
            assert_eq!(color(invalid), None, "{invalid}");
        }
    }

    #[test]
    fn invalid_unicode_colors_and_negative_sizes_are_ignored() {
        for value in ["#aéaaa", "#aéaaaaa", "#１２３"] {
            assert_eq!(color(value), None);
        }
        let kind = NodeKind::Element {
            namespace: Namespace::Html,
            name: "div".into(),
            attributes: alloc::vec![(
                "style".into(),
                "width:5px;width:-1px;height:-2px;padding:-3px;font-size:0px".into()
            )],
        };
        let style = compute(&kind, None, &StyleIndex::new(Vec::new())).unwrap();
        assert_eq!(style.width, Some(5.0));
        assert_eq!(style.height, None);
        assert_eq!(style.padding, 0.0);
        assert_eq!(style.font_size, 0.0);
        let negative_font = compute(&element("font-size:-1px"), None, &StyleIndex::new(Vec::new()))
            .unwrap();
        assert_eq!(negative_font.font_size, 16.0);
    }

    #[test]
    fn zero_font_size_inherits_and_resolves_em_lengths_without_a_minimum_size() {
        let index = StyleIndex::new(Vec::new());
        let parent = compute(&element("font-size:0px"), None, &index).unwrap();
        assert_eq!(parent.font_size, 0.0);

        let inherited = compute(&element("color:blue"), Some(&parent), &index).unwrap();
        assert_eq!(inherited.font_size, 0.0);
        let em = compute(&element("font-size:1em"), Some(&parent), &index).unwrap();
        assert_eq!(em.font_size, 0.0);
        let calc = compute(
            &element("font-size:calc(1em + 0px)"),
            Some(&parent),
            &index,
        )
        .unwrap();
        assert_eq!(calc.font_size, 0.0);
    }

    #[test]
    fn specification_primary_font_control_defaults_keep_computed_auto_and_hidden_state() {
        let index = StyleIndex::new(Vec::new());
        let input = |size: &str| NodeKind::Element {
            namespace: Namespace::Html,
            name: "input".into(),
            attributes: alloc::vec![("size".into(), size.into())],
        };
        let default = compute(&input("invalid"), None, &index).unwrap();
        assert_eq!(default.display, Display::InlineBlock);
        assert_eq!((default.width, default.height), (None, None));
        assert_eq!(
            default.font.families.as_deref().unwrap()[0].as_ref(),
            "Arial"
        );
        let bounded = compute(&input("999"), None, &index).unwrap();
        assert_eq!((bounded.width, bounded.height), (None, None));

        let textarea = NodeKind::Element {
            namespace: Namespace::Html,
            name: "textarea".into(),
            attributes: alloc::vec![("cols".into(), "999".into()), ("rows".into(), "999".into())],
        };
        let textarea = compute(&textarea, None, &index).unwrap();
        assert_eq!(textarea.display, Display::InlineBlock);
        assert_eq!(textarea.white_space, WhiteSpace::PreWrap);
        assert_eq!((textarea.width, textarea.height), (None, None));

        let hidden = NodeKind::Element {
            namespace: Namespace::Html,
            name: "input".into(),
            attributes: alloc::vec![("type".into(), "hidden".into())],
        };
        assert_eq!(
            compute(&hidden, None, &index).unwrap().display,
            Display::None
        );
    }

    #[test]
    fn specification_svg_filter_presentation_uses_shared_typed_cascade() {
        for (source, expected) in [
            ("<svg><g id=host filter='invert()'/></svg>", "invert(1)"),
            ("<svg><g id=host style='filter:invert()'/></svg>", "invert(1)"),
            ("<style>g{filter:brightness(150%)}</style><svg><g id=host filter='invert()'/></svg>", "brightness(1.5)"),
            ("<style>g{filter:brightness(150%)}</style><svg><g id=host filter='invert()' style='filter:none'/></svg>", "none"),
            ("<svg><g id=host filter='brightness(calc(sign(1em)))'/></svg>", "brightness(1)"),
            ("<svg><g id=host filter='invert(-1)'/></svg>", "none"),
        ] {
            let document = crate::html::parse(source, 64).unwrap();
            let host = crate::selector::get_element_by_id(&document, document.root(), "host").unwrap().unwrap();
            let mut session = crate::session::RenderSession::new(document);
            assert_eq!(session.computed_style(host).unwrap().computed_css_value("filter", Default::default()).as_deref(), Some(expected), "{source}");
        }
    }

    #[test]
    fn specification_color_filter_admission_order_and_computed_state() {
        assert_eq!(slots("filter"), &[233]);
        assert!(!inherited_property(233));
        assert!(!paint_only_property("filter"), "fixed descendants require geometry invalidation");
        for (raw, expected) in [
            ("none", "none"), ("invert()", "invert(1)"),
            ("BRIGHTNESS(150%) contrast(.5)", "brightness(1.5) contrast(0.5)"),
            ("grayscale(200%)opacity(50%)", "grayscale(1) opacity(0.5)"),
            ("brightness(calc(-10%))", "brightness(0)"),
            ("contrast(calc(-10))", "contrast(0)"),
            ("invert(calc(-10))", "invert(0)"),
            ("opacity(300%) sepia(calc(3))", "opacity(1) sepia(1)"),
            ("invert(/* omitted */)", "invert(1)"),
            ("hue-rotate(2turn)", "hue-rotate(720deg)"),
            ("hue-rotate(calc(180deg + 180deg))", "hue-rotate(360deg)"),
            ("invert(calc(.5 + .25))", "invert(0.75)"),
            (r"in\76 ert(1)", "invert(1)"),
        ] {
            let style = compute(&element(&alloc::format!("filter:{raw}")), None, &StyleIndex::new(Vec::new())).unwrap();
            assert_eq!(style.computed_css_value("filter", Default::default()).as_deref(), Some(expected), "{raw}");
            assert!(supports_property_value("filter", raw), "{raw}");
        }
        for raw in ["invert(-1)", "invert(1px)", "hue-rotate(10)", "hue-rotate(10%)", "invert(1, 0)", "none invert()", "invert() none", "blur(1px)", "url(#filter)", "drop-shadow(1px 2px red)", "", "invert(\"1\")"] {
            assert!(!supports_property_value("filter", raw), "{raw}");
        }
        let over_limit = "invert() ".repeat(lumen_common::filter::MAX_COLOR_FILTERS + 1);
        assert!(!supports_property_value("filter", &over_limit));
        let parent = compute(&element("filter:invert()"), None, &StyleIndex::new(Vec::new())).unwrap();
        assert!(compute(&element(""), Some(&parent), &StyleIndex::new(Vec::new())).unwrap().filters.is_none());
        assert_eq!(compute(&element("filter:inherit"), Some(&parent), &StyleIndex::new(Vec::new())).unwrap().filters, parent.filters);
        assert!(compute(&element("filter:invert();all:initial"), None, &StyleIndex::new(Vec::new())).unwrap().filters.is_none());
        let contextual = compute(&element("font-size:20px;filter:brightness(sign(1em))"), None, &StyleIndex::new(Vec::new())).unwrap();
        assert_eq!(contextual.computed_css_value("filter", Default::default()).as_deref(), Some("brightness(1)"));
    }

    #[test]
    fn specification_color_filter_specified_values_preserve_numeric_source() {
        for (raw, specified, computed) in [
            ("brightness(300%)", "brightness(300%)", "brightness(3)"),
            ("grayscale(300%)", "grayscale(100%)", "grayscale(1)"),
            ("invert(2)", "invert(1)", "invert(1)"),
            ("opacity(calc(-10%))", "opacity(calc(-10%))", "opacity(0)"),
            ("sepia(calc(300%))", "sepia(calc(300%))", "sepia(1)"),
            ("hue-rotate(2turn)", "hue-rotate(2turn)", "hue-rotate(720deg)"),
            ("hue-rotate(0)", "hue-rotate(0deg)", "hue-rotate(0deg)"),
        ] {
            let block = DeclarationBlock::parse(&alloc::format!("filter:{raw}")).unwrap();
            assert_eq!(block.value("filter").unwrap().0, specified, "{raw}");
            assert_eq!(serialize_cssom_property_value("filter", raw).as_deref(), Some(specified));
            let style = compute(&element(&alloc::format!("filter:{raw}")), None, &StyleIndex::new(Vec::new())).unwrap();
            assert_eq!(style.computed_css_value("filter", Default::default()).as_deref(), Some(computed));
        }
    }

    #[test]
    fn specification_color_filter_computed_values_share_container_numeric_context() {
        let document = crate::html::parse("<style>#container{container-type:inline-size;width:100px}</style><div id=container><div id=target></div></div>", 32).unwrap();
        let target = crate::selector::query_selector(&document, document.root(), "#target").unwrap().unwrap();
        struct EmptyText;
        impl TextShaper for EmptyText {
            fn shape(&self, _: &str, _: f32) -> Result<crate::paint::ShapedRun, ()> {
                Ok(crate::paint::ShapedRun { glyphs: Arc::from([]), width: 0.0 })
            }
            fn ascent(&self, size: f32) -> f32 { size }
            fn line_height(&self, size: f32) -> f32 { size }
        }
        let mut session = crate::session::RenderSession::new(document);
        // filter-computed.html: 2cqw - 10px = -8px, hence sign(...) = -1.
        for (name, prefix, expected) in [("brightness", "10", "5"), ("contrast", "10", "5"),
            ("grayscale", "100%", "0.5"), ("invert", "100%", "0.5"),
            ("opacity", "100%", "0.5"), ("saturate", "10", "5"), ("sepia", "100%", "0.5")] {
            let delta = if prefix == "100%" { "50%" } else { "5" };
            session.document_mut().set_attribute(target, "style", &alloc::format!("filter:{name}(calc({prefix} + sign(2cqw - 10px) * {delta}))")).unwrap();
            session.display_list(120, 100, &EmptyText).unwrap();
            assert_eq!(session.computed_style(target).unwrap().computed_css_value("filter", Default::default()).as_deref(),
                Some(alloc::format!("{name}({expected})").as_str()), "{name}");
        }
    }

    #[test]
    fn specification_field_sizing_registry_cascade_and_computed_values_are_canonical() {
        assert_eq!(slots("field-sizing"), &[232]);
        assert!(!inherited_property(232));
        assert_eq!(
            transition_value_kind("field-sizing"),
            TransitionValueKind::Discrete
        );
        for (specified, expected) in [("fixed", "fixed"), ("CONTENT", "content")] {
            let declarations = typed_declarations("field-sizing", specified, 0).unwrap();
            assert_eq!(declarations.len(), 1);
            let mut style = Style::initial();
            declarations[0].value.apply(&mut style);
            assert_eq!(style.field_sizing.as_str(), expected);
            assert_eq!(
                serialize_cssom_property_value("field-sizing", specified).as_deref(),
                Some(expected)
            );
        }
        for value in ["none", "auto", "content fixed", "legacy", ""] {
            assert!(
                typed_declarations("field-sizing", value, 0).is_ok_and(|values| values.is_empty())
            );
        }
        let document=crate::html::parse("<style>body{field-sizing:content}#inherit{field-sizing:inherit}#reset{field-sizing:content;all:initial}#variable{--mode:content;field-sizing:var(--mode)}textarea{white-space:pre-wrap}#off{white-space:normal}</style><input id=default><input id=inherit><input id=reset><input id=variable><textarea id=wrap wrap=off></textarea><textarea id=off wrap=off></textarea>",128).unwrap();
        let rules=StyleIndex::new(parse("body{field-sizing:content}#inherit{field-sizing:inherit}#reset{field-sizing:content;all:initial}#variable{--mode:content;field-sizing:var(--mode)}#off{white-space:normal}").unwrap());
        for (selector, expected) in [
            ("#default", FieldSizing::Fixed),
            ("#inherit", FieldSizing::Content),
            ("#reset", FieldSizing::Fixed),
            ("#variable", FieldSizing::Content),
        ] {
            let node = crate::selector::query_selector(&document, document.root(), selector)
                .unwrap()
                .unwrap();
            let body = document.parent(node).unwrap().unwrap();
            let parent = compute_node(&document, body, None, &rules).unwrap();
            assert_eq!(
                compute_node(&document, node, Some(&parent), &rules)
                    .unwrap()
                    .field_sizing,
                expected
            );
        }
        for (selector, expected) in [("#wrap", WhiteSpace::Pre), ("#off", WhiteSpace::Normal)] {
            let node = crate::selector::query_selector(&document, document.root(), selector)
                .unwrap()
                .unwrap();
            assert_eq!(
                compute_node(&document, node, None, &rules)
                    .unwrap()
                    .white_space,
                expected
            );
        }
    }
    #[test]
    fn unsupported_rule_does_not_abort_later_rules() {
        let rules =
            parse(":root { --color: red } @media print { p { color: red } } p { color: blue }")
                .unwrap();
        assert_eq!(rules.len(), 3);
        let kind = NodeKind::Element {
            namespace: Namespace::Html,
            name: "p".into(),
            attributes: Vec::new(),
        };
        assert_eq!(
            compute(&kind, None, &StyleIndex::new(rules))
                .unwrap()
                .color
                .b,
            255
        );
    }

    #[test]
    fn generated_content_parser_keeps_typed_tokens_and_limits_input() {
        let parsed = parse_generated_content(
            r#""before " attr(data-label, "fallback") url(../icon.svg) counter(step, upper-roman) counters(section, ".", decimal) open-quote / "spoken""#,
        )
        .unwrap();
        let GeneratedContent::Items(items) = parsed else {
            panic!("expected generated items");
        };
        assert_eq!(items.len(), 7);
        assert_eq!(items[0], GeneratedContentItem::String(Arc::from("before ")));
        assert_eq!(
            items[1],
            GeneratedContentItem::Attribute {
                name: Arc::from("data-label"),
                fallback: Some(Arc::from("fallback")),
            }
        );
        assert_eq!(
            items[2],
            GeneratedContentItem::Url(Arc::from("../icon.svg"))
        );
        assert_eq!(
            items[3],
            GeneratedContentItem::Counter {
                name: Arc::from("step"),
                style: Arc::from("upper-roman"),
            }
        );
        assert_eq!(
            items[4],
            GeneratedContentItem::Counters {
                name: Arc::from("section"),
                separator: Arc::from("."),
                style: Arc::from("decimal"),
            }
        );
        assert_eq!(items[5], GeneratedContentItem::OpenQuote);
        assert_eq!(
            items[6],
            GeneratedContentItem::AlternativeText(
                alloc::vec![GeneratedContentItem::String(Arc::from("spoken"))].into()
            )
        );
        assert_eq!(
            parse_generated_content("normal"),
            Some(GeneratedContent::Normal)
        );
        assert_eq!(
            parse_generated_content("none"),
            Some(GeneratedContent::None)
        );
        assert!(parse_generated_content("'unterminated").is_none());
        for invalid in [
            "open-quote / no-open-quote",
            "close-quote / no-close-quote",
            "'hello' / 'hi' no-close-quote",
            "url(icon.svg) / url(alt.svg)",
            "'hello' / url(https://example.test/picture.svg)",
        ] {
            assert!(
                parse_generated_content(invalid).is_none(),
                "invalid alternative text was accepted: {invalid}"
            );
        }
        assert!(parse_counter_declaration(CounterProperty::Set, "default 2").is_none());
        assert!(parse_generated_content(&alloc::format!(
            "\"{}\"",
            "x".repeat(MAX_GENERATED_CONTENT_BYTES)
        ))
        .is_none());
        assert!(matches!(
            parse_generated_content("image-set(url(a.png) 1x)").unwrap(),
            GeneratedContent::Items(items)
                if matches!(items.first(), Some(GeneratedContentItem::Image(raw)) if &**raw == "image-set(url(\"a.png\") 1x)")
        ));
    }

    #[test]
    fn specification_generated_image_sets_share_image_grammar_and_source_serialization() {
        for property in ["background-image", "border-image-source", "content"] {
            for prefix in ["image-set", "-webkit-image-set"] {
                let raw = alloc::format!("{prefix}(url(a.png) 1x, 'b.png' 3x)");
                let declaration = DeclarationBlock::parse(&alloc::format!("{property}:{raw}")).unwrap();
                assert_eq!(declaration.value(property).unwrap().0,
                    "image-set(url(\"a.png\") 1x, url(\"b.png\") 3x)");
                assert!(!supports_property_value(property, &alloc::format!("{prefix}(none, url(a.png) 1x)")));
                assert!(!supports_property_value(property, &alloc::format!("{prefix}(n\\6f ne, url(a.png) 1x)")));
            }
        }
        for raw in ["image-set(url(a.png) 0x)", "image-set(url(a.png) type('image/unsupported'))"] {
            assert!(supports_property_value("content", raw), "valid image syntax survives unavailable candidates: {raw}");
        }
        assert_eq!(serialize_content_declaration("'text' image-set('none' 2x)").as_deref(),
            Some("\"text\" image-set(url(\"none\") 2x)"));
    }

    #[test]
    fn counter_declarations_are_typed_bounded_and_cssom_serialization_is_canonical() {
        assert_eq!(
            parse_counter_directives("chapter 2 reversed(section)", true, 0),
            Some(Some(
                alloc::vec![
                    CounterDirective {
                        name: Arc::from("chapter"),
                        value: 2,
                        reversed: false,
                        explicit_value: true,
                        math_expression: None,
                    },
                    CounterDirective {
                        name: Arc::from("section"),
                        value: 0,
                        reversed: true,
                        explicit_value: false,
                        math_expression: None,
                    },
                ]
                .into()
            ))
        );
        assert_eq!(
            parse_counter_directives("section -3 section 4", false, 1),
            Some(Some(
                alloc::vec![
                    CounterDirective {
                        name: Arc::from("section"),
                        value: -3,
                        reversed: false,
                        explicit_value: true,
                        math_expression: None,
                    },
                    CounterDirective {
                        name: Arc::from("section"),
                        value: 4,
                        reversed: false,
                        explicit_value: true,
                        math_expression: None,
                    },
                ]
                .into()
            ))
        );
        assert_eq!(parse_counter_directives("none", false, 1), Some(None));
        assert!(parse_counter_directives("none step", false, 1).is_none());
        assert!(parse_counter_directives("initial 2", false, 1).is_none());
        assert!(parse_counter_directives("x 2.5", false, 1).is_none());

        assert_eq!(
            serialize_counter_declaration(CounterProperty::Reset, "chapter"),
            Some("chapter 0".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Increment, "myCounter"),
            Some("myCounter 1".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Set, "chapter"),
            Some("chapter 0".into())
        );
        assert_eq!(
            serialize_counter_declaration(
                CounterProperty::Reset,
                "chapter reversed(chapter) reversed(section) 0"
            ),
            Some("chapter 0 reversed(chapter) reversed(section) 0".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Reset, "reversed(chapter)"),
            Some("reversed(chapter)".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Reset, r"a\ 8 9"),
            Some(r"a\ 8 9".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Increment, "section +001"),
            Some("section 1".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Set, "section -0"),
            Some("section 0".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Reset, "section calc(1)"),
            Some("section calc(1)".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Reset, "section calc(-2.5)"),
            Some("section calc(-2.5)".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Reset, "section calc(2.5)"),
            Some("section calc(2.5)".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Increment, "section calc(1 + sign(2))"),
            Some("section calc(1 + sign(2))".into())
        );
        let parsed_calc = parse_counter_declaration(CounterProperty::Reset, "section calc(-2.5)")
            .unwrap()
            .unwrap();
        assert_eq!(
            serialize_counter_directives(CounterProperty::Reset, Some(&parsed_calc)),
            Some("section -2".into())
        );
        for (source, expected) in [
            ("counter calc(999999999999)", "counter 2100000000"),
            ("counter calc(-999999999999)", "counter -2100000000"),
        ] {
            let parsed = parse_counter_declaration(CounterProperty::Set, source)
                .unwrap()
                .unwrap();
            assert_eq!(
                serialize_counter_directives(CounterProperty::Set, Some(&parsed)),
                Some(expected.into())
            );
        }
        assert!(serialize_counter_declaration(
            CounterProperty::Increment,
            "section reversed(section)"
        )
        .is_none());
        assert!(serialize_counter_declaration(
            CounterProperty::Set,
            "section calc(10 + (5 * sign(2cqw - 10px)))"
        )
        .is_none());
        assert_eq!(
            serialize_counter_directives(CounterProperty::Set, None),
            Some("none".into())
        );
        assert_eq!(
            serialize_counter_declaration(CounterProperty::Reset, "none"),
            Some("none".into())
        );

        assert_eq!(
            serialize_content_declaration("open-quote 'hello' counter(chapter, DECIMAL) / 'alt'"),
            Some("open-quote \"hello\" counter(chapter) / \"alt\"".into())
        );
        assert_eq!(
            serialize_content_declaration("counter(chapter, NONE) counters(section, '.', DECIMAL)"),
            Some("counter(chapter, none) counters(section, \".\")".into())
        );
        assert_eq!(
            serialize_quotes_declaration("'left' \"right\" 'inner' 'end'"),
            Some("\"left\" \"right\" \"inner\" \"end\"".into())
        );
    }

    #[test]
    fn quotes_parser_keeps_bounded_pairs_and_keywords() {
        assert_eq!(parse_quotes("auto"), Some(Quotes::Auto));
        assert_eq!(parse_quotes("none"), Some(Quotes::None));
        assert_eq!(parse_quotes("match-parent"), Some(Quotes::MatchParent));
        assert_eq!(
            parse_quotes(r#""outer \" left" "right" "inner" "end""#),
            Some(Quotes::Pairs(
                alloc::vec![
                    (Arc::from("outer \" left"), Arc::from("right")),
                    (Arc::from("inner"), Arc::from("end")),
                ]
                .into()
            ))
        );
        assert!(parse_quotes("\"unpaired\"").is_none());
        assert!(parse_quotes("\"one\" two").is_none());
        let too_many = alloc::vec!["\"a\" \"b\""; MAX_QUOTES_PAIRS + 1].join(" ");
        assert!(parse_quotes(&too_many).is_none());
    }

    #[test]
    fn q_default_pseudos_use_open_and_close_quote_content() {
        let document = crate::html::parse("<main><q id='target'>quoted</q></main>", 64).unwrap();
        let target = crate::selector::query_selector(&document, document.root(), "#target")
            .unwrap()
            .unwrap();
        let index = StyleIndex::new(Vec::new());
        let origin = compute_node(&document, target, None, &index).unwrap();
        let before = index
            .compute_pseudo(&document, target, &origin, PseudoElement::Before, None)
            .unwrap()
            .unwrap();
        let after = index
            .compute_pseudo(&document, target, &origin, PseudoElement::After, None)
            .unwrap()
            .unwrap();
        assert_eq!(
            before.content,
            GeneratedContent::Items(alloc::vec![GeneratedContentItem::OpenQuote].into())
        );
        assert_eq!(
            after.content,
            GeneratedContent::Items(alloc::vec![GeneratedContentItem::CloseQuote].into())
        );

        let overrides = StyleIndex::new(
            parse("q::before { content: normal; quotes: none } q::after { quotes: '<' '>' }")
                .unwrap(),
        );
        assert!(overrides
            .compute_pseudo(&document, target, &origin, PseudoElement::Before, None)
            .unwrap()
            .is_none());
        assert_eq!(
            overrides
                .compute_pseudo(&document, target, &origin, PseudoElement::After, None)
                .unwrap()
                .unwrap()
                .style
                .quotes(),
            &Quotes::Pairs(alloc::vec![(Arc::from("<"), Arc::from(">"))].into())
        );
    }

    #[test]
    fn list_item_defaults_inherit_style_and_build_the_marker_counter() {
        let document = crate::html::parse(
            "<ol id='items' start='7'><li id='first'></li><li id='second' value='12'></li></ol>",
            32,
        )
        .unwrap();
        let list = crate::selector::query_selector(&document, document.root(), "#items")
            .unwrap()
            .unwrap();
        let first = crate::selector::query_selector(&document, document.root(), "#first")
            .unwrap()
            .unwrap();
        let second = crate::selector::query_selector(&document, document.root(), "#second")
            .unwrap()
            .unwrap();
        let index = StyleIndex::new(
            parse(
                "#items { list-style-type: upper-alpha } #second { list-style-position: inside } #second::marker { content: counter(list-item, upper-alpha) '>' }",
            )
            .unwrap(),
        );

        let list_style = compute_node(&document, list, None, &index).unwrap();
        assert_eq!(list_style.list_style_type, ListStyleType::UpperAlpha);
        assert_eq!(list_style.counter_reset.as_deref().unwrap()[0].value, 6);
        let first_style = compute_node(&document, first, Some(&list_style), &index).unwrap();
        let second_style = compute_node(&document, second, Some(&list_style), &index).unwrap();
        assert_eq!(first_style.display, Display::ListItem);
        assert_eq!(first_style.list_style_type, ListStyleType::UpperAlpha);
        assert_eq!(second_style.list_style_position, ListStylePosition::Inside);
        assert_eq!(second_style.counter_set.as_deref().unwrap()[0].value, 12);
        let marker = index
            .compute_pseudo(
                &document,
                second,
                &second_style,
                PseudoElement::Marker,
                None,
            )
            .unwrap()
            .unwrap();
        assert_eq!(
            marker.content,
            GeneratedContent::Items(
                alloc::vec![
                    GeneratedContentItem::Counter {
                        name: Arc::from("list-item"),
                        style: Arc::from("upper-alpha"),
                    },
                    GeneratedContentItem::String(Arc::from(">")),
                ]
                .into()
            )
        );
    }

    #[test]
    fn list_style_shorthand_assigns_ambiguous_none_components() {
        let document = crate::html::parse(
            "<div id='single'></div><div id='pair'></div><div id='none-type'></div><div id='type-none'></div>",
            64,
        )
        .unwrap();
        let index = StyleIndex::new(
            parse(
                "#single { display:list-item; list-style:none } #pair { display:list-item; list-style:none none } #none-type { display:list-item; list-style:none square } #type-none { display:list-item; list-style:square none }",
            )
            .unwrap(),
        );

        for id in ["single", "pair"] {
            let node = crate::selector::query_selector(
                &document,
                document.root(),
                &alloc::format!("#{id}"),
            )
            .unwrap()
            .unwrap();
            let style = compute_node(&document, node, None, &index).unwrap();
            assert_eq!(style.list_style_type, ListStyleType::None, "#{id}");
            assert_eq!(style.list_style_position, ListStylePosition::Outside);
            assert!(index
                .compute_pseudo(&document, node, &style, PseudoElement::Marker, None)
                .unwrap()
                .is_none());
        }

        for id in ["none-type", "type-none"] {
            let node = crate::selector::query_selector(
                &document,
                document.root(),
                &alloc::format!("#{id}"),
            )
            .unwrap()
            .unwrap();
            let style = compute_node(&document, node, None, &index).unwrap();
            assert_eq!(style.list_style_type, ListStyleType::Square, "#{id}");
            let marker = index
                .compute_pseudo(&document, node, &style, PseudoElement::Marker, None)
                .unwrap()
                .unwrap();
            assert_eq!(
                marker.content,
                GeneratedContent::Items(
                    alloc::vec![GeneratedContentItem::String(Arc::from("▪"))].into()
                )
            );
        }
        assert!(
            typed_declarations("list-style", "url(marker.png) square", 0)
                .unwrap()
                .iter()
                .any(|declaration| matches!(
                    &declaration.value,
                    Value::ListStyleImage(Some(url)) if url.as_ref() == "marker.png"
                )),
            "image shorthand must retain its image component"
        );
    }

    // /css/css-color/light-dark-image.html
    // /css/css-color/light-dark-image-none.html
    // /css/css-color/light-dark-image.html
    #[test]
    fn specification_content_images_select_before_inheritance_and_nested_legacy_cross_fade() {
        let index=StyleIndex::new(Vec::new());
        let source="content:light-dark(url(light.png),url(dark.png));color-scheme:dark";
        let parent=compute(&element(source),None,&index).unwrap();
        assert_eq!(parent.computed_css_value("content",computed_values::ComputedValueContext::default()).unwrap(),"url(\"dark.png\")");
        let child=compute(&element("content:inherit;color-scheme:light"),Some(&parent),&index).unwrap();
        assert_eq!(child.generated_content(),parent.generated_content());
        assert!(declaration_block::DeclarationBlock::parse(source).unwrap().value("content").unwrap().0.contains("light-dark("));
        let forbidden="image-set(-webkit-cross-fade(url(a),image-set(url(b) 1x),50%) 1x)";
        for property in ["background-image","border-image-source","list-style-image","content"] {
            assert!(typed_declarations(property,forbidden,0).unwrap().is_empty(),"{property} rejects indirect nested image-set");
        }
        let nested="-webkit-cross-fade(image-set(light-dark(url(light-a),url(dark-a)) 1x),image-set(light-dark(url(light-b),url(dark-b)) 1x),50%)";
        let style=compute(&element(&alloc::format!("color-scheme:dark;background-image:{nested}")),None,&index).unwrap();
        let computed=style.computed_css_value("background-image",computed_values::ComputedValueContext::default()).unwrap();
        assert!(computed.contains("dark-a")&&computed.contains("dark-b")&&!computed.contains("light-a")&&!computed.contains("light-b"));
        assert!(parse_generated_content("light-dark(red,blue)").is_none());
        assert!(!image_source::nested_image_set(r#"image-set(url("image-set(x)"))"#));
        assert!(image_source::nested_image_set(r"image-set(l\69 ght-dark(none,\69 mage-set(url(a))))"));
    }

    #[test]
    fn specification_marker_images_select_before_inheritance_and_preserve_declared_source() {
        use computed_values::ComputedValueContext;
        let index=StyleIndex::new(Vec::new());
        let source="list-style-image:light-dark(url(light.png),none);color-scheme:dark";
        let parent=compute(&element(source),None,&index).unwrap();
        assert_eq!(parent.computed_css_value("list-style-image",ComputedValueContext::default()).unwrap(),"image(rgba(0, 0, 0, 0))");
        let child=compute(&element("color-scheme:light;list-style-image:inherit"),Some(&parent),&index).unwrap();
        assert_eq!(child.computed_css_value("list-style-image",ComputedValueContext::default()),parent.computed_css_value("list-style-image",ComputedValueContext::default()));
        let block=declaration_block::DeclarationBlock::parse(source).unwrap();
        assert!(block.value("list-style-image").unwrap().0.contains("light-dark("));
        let gradient=compute(&element("list-style:light-dark(linear-gradient(red,blue),none) inside"),None,&index).unwrap();
        assert!(gradient.computed_css_value("list-style-image",ComputedValueContext::default()).unwrap().starts_with("linear-gradient("));
    }

    #[test]
    fn list_style_image_is_inherited_and_kept_in_the_shorthand() {
        let document = crate::html::parse(
            "<ul id='list'><li id='item'></li></ul><div id='none'></div>",
            32,
        )
        .unwrap();
        let index = StyleIndex::new(
            parse(
                "#list { list-style-image: url(marker.png); list-style-type: none } #none { display:list-item; list-style: none url(other.png) inside }",
            )
            .unwrap(),
        );
        let list = crate::selector::query_selector(&document, document.root(), "#list")
            .unwrap()
            .unwrap();
        let item = crate::selector::query_selector(&document, document.root(), "#item")
            .unwrap()
            .unwrap();
        let none = crate::selector::query_selector(&document, document.root(), "#none")
            .unwrap()
            .unwrap();
        let list_style = compute_node(&document, list, None, &index).unwrap();
        let item_style = compute_node(&document, item, Some(&list_style), &index).unwrap();
        assert_eq!(
            item_style.list_style_image.as_deref(),
            Some("marker.png"),
            "the source URL remains shared and inherits through list items"
        );
        let marker = index
            .compute_pseudo(&document, item, &item_style, PseudoElement::Marker, None)
            .unwrap()
            .unwrap();
        assert!(matches!(marker.content, GeneratedContent::Items(items) if items.is_empty()));

        let shorthand_style = compute_node(&document, none, None, &index).unwrap();
        assert_eq!(shorthand_style.list_style_type, ListStyleType::None);
        assert_eq!(shorthand_style.list_style_position, ListStylePosition::Inside);
        assert_eq!(
            shorthand_style.list_style_image.as_deref(),
            Some("other.png")
        );
        assert_eq!(
            typed_declarations("list-style", "square none", 0)
                .unwrap()
                .len(),
            3,
            "the shorthand resets all three longhands"
        );
    }

    #[test]
    fn malformed_at_keyword_preludes_discard_one_rule_and_keep_following_rules() {
        assert!(matches!(
            rule_boundary("@ import url(a); div{}"),
            Some(RuleBoundary::Block(_))
        ));
        assert!(matches!(rule_boundary("@1import; div{}"), Some(RuleBoundary::Block(_))));
        assert!(matches!(rule_boundary("@-1import; div{}"), Some(RuleBoundary::Block(_))));
        assert!(matches!(
            rule_boundary("@import url(a);"),
            Some(RuleBoundary::Statement(_))
        ));

        let document = crate::html::parse("<div id='target'></div>", 16).unwrap();
        for malformed in [
            "@ import bogus; div",
            "@1import bogus; div",
            "@-1import bogus; div",
        ] {
            let rules = parse(&alloc::format!(
                "{malformed} {{ color:red }} * {{ color:green }}"
            ))
            .unwrap();
            let target = crate::selector::query_selector(&document, document.root(), "#target")
                .unwrap()
                .unwrap();
            let style = compute_node(&document, target, None, &StyleIndex::new(rules)).unwrap();
            assert_eq!(
                style.color,
                color("green").unwrap(),
                "a malformed at-keyword must not swallow the later qualified rule: {malformed}"
            );
        }
    }

