    #[test]
    fn specification_font_family_display_defaults_keep_omission_conditions_and_sheet_order() {
        let first=parse_stylesheet("@font-feature-values Target, 'serif' {font-display:block;@styleset{alternate:1 2}} @font-face{font-family:Target;src:url(a)} @font-face{font-family:Target;src:url(b);font-display:auto} @font-face{font-family:Other;src:url(c)}").unwrap();
        let second=parse_stylesheet("@media (min-width:600px){@font-feature-values target{font-display:swap}} @supports (unknown:value){@font-feature-values Target{font-display:optional}} @font-feature-values serif{font-display:optional}").unwrap();
        assert_eq!(first.family_display.len(),1);
        assert_eq!(first.family_display[0].families.len(),2);
        assert_eq!(second.family_display.len(),1,"false supports groups are pruned before family resolution");
        assert!(parse_stylesheet("@font-feature-values serif{font-display:optional}").unwrap().family_display.is_empty(),
            "an unquoted generic family invalidates the family-name prelude");
        assert!(parse_stylesheet("@font-feature-values Target, serif{font-display:optional}").unwrap().family_display.is_empty(),
            "an invalid family invalidates the entire family list");
        let mut groups=[first,second];
        let faces=canonicalize_font_faces(&mut groups);
        let narrow=MediaEnvironment{width:300.,..MediaEnvironment::default()};
        let wide=MediaEnvironment{width:800.,..MediaEnvironment::default()};
        assert!(!faces[0].display_specified);
        assert_eq!(faces[0].display,FontDisplay::Auto,"specified descriptor remains omitted/initial");
        assert_eq!(faces[0].effective_display(narrow),FontDisplay::Block);
        assert_eq!(faces[0].effective_display(wide),FontDisplay::Swap);
        assert!(faces[1].display_specified);
        assert_eq!(faces[1].effective_display(wide),FontDisplay::Auto,"explicit auto wins over family default");
        assert_eq!(faces[2].effective_display(wide),FontDisplay::Auto);
        let replacement=parse_stylesheet("@font-feature-values Target{font-display:fallback;font-display:invalid;font-display:optional!important}").unwrap();
        groups[1]=replacement;
        let faces=canonicalize_font_faces(&mut groups);
        assert_eq!(faces[0].effective_display(wide),FontDisplay::Fallback,"invalid and important descriptors do not replace the last valid value");
    }

    #[test]
    fn specification_appearance_keywords_cascade_alias_and_author_devolution() {
        let document = crate::html::parse("<style>input{appearance:auto}#primitive{-webkit-appearance:none}#ordinary{appearance:checkbox}#reset{all:initial}#styled{border-color:initial}@layer low,high;@layer low{#layer{background:blue}}@layer high{#layer{background:revert-layer}#rollback{border:revert}}</style><input id=native type=checkbox><input id=primitive type=checkbox><div id=ordinary></div><input id=reset type=radio><input id=styled type=radio><input id=layer><input id=rollback>", 128).unwrap();
        let rules = StyleIndex::new(parse("input{appearance:auto}#primitive{-webkit-appearance:none}#ordinary{appearance:checkbox}#reset{all:initial}#styled{border-color:initial}@layer low,high;@layer low{#layer{background:blue}}@layer high{#layer{background:revert-layer}#rollback{border:revert}} ").unwrap());
        let value = |id: &str| {
            let node = crate::selector::get_element_by_id(&document, document.root(), id).unwrap().unwrap();
            compute_node(&document, node, None, &rules).unwrap()
        };
        assert_eq!(value("native").appearance, Appearance::Auto);
        assert_eq!(value("primitive").appearance, Appearance::None);
        assert_eq!(value("ordinary").appearance, Appearance::Checkbox);
        assert_eq!(value("reset").appearance, Appearance::None);
        assert!(value("styled").widget_devolved);
        assert!(value("layer").widget_devolved);
        assert!(!value("rollback").widget_devolved);
        for word in ["none", "auto", "base", "base-select", "textfield", "menulist-button", "checkbox", "radio", "searchfield", "textarea", "menulist", "listbox", "meter", "progress-bar", "button"] {
            let parsed = typed_declarations("appearance", word, 0).unwrap();
            assert_eq!(parsed.len(), 1);
            assert_eq!(serialize_cssom_property_value("appearance", word).as_deref(), Some(word));
        }
        for invalid in ["auto none", "slider-vertical", "square-button", "button()", "1", ""] {
            assert!(typed_declarations("appearance", invalid, 0).unwrap().is_empty());
        }
        let parent = value("primitive");
        let node = crate::selector::get_element_by_id(&document, document.root(), "native").unwrap().unwrap();
        assert_eq!(compute_node(&document, node, Some(&parent), &rules).unwrap().appearance, Appearance::Auto);
    }

    #[test]
    fn specification_placeholder_shared_selector_cascade_and_typographic_applicability() {
        assert_eq!(parse_selector("input::placeholder",0).unwrap().pseudo_element,Some(PseudoElement::Placeholder));
        assert!(parse_selector("input:placeholder",0).is_err());
        assert!(parse_selector("input::placeholder(foo)",0).is_err());
        let document=crate::html::parse("<!doctype html><input id=control style='font-size:10px;line-height:20px;color:blue;background:lime'>",32).unwrap();
        let control=crate::selector::get_element_by_id(&document,document.root(),"control").unwrap().unwrap();
        for (declaration,color,font) in [
            ("",Rgba{r:117,g:117,b:117,a:255},10.0),
            ("color:inherit;font:30px/0 serif;line-height:0;vertical-align:100px;direction:rtl;writing-mode:vertical-rl;background-color:inherit",Rgba{r:0,g:0,b:255,a:255},30.0),
            ("color:red;color:revert;font-size:30px;font-size:revert",Rgba{r:117,g:117,b:117,a:255},10.0),
            ("all:inherit",Rgba{r:0,g:0,b:255,a:255},10.0),
        ] {
            let index=StyleIndex::new(parse(&alloc::format!("input::placeholder{{{declaration}}}")).unwrap());
            let origin=compute_node(&document,control,None,&index).unwrap();
            let pseudo=index.compute_pseudo_computed(&document,control,&origin,PseudoElement::Placeholder,None).unwrap();
            assert_eq!(pseudo.color,color,"{declaration}: actual UA/author/inheritance cascade");
            assert_eq!(pseudo.font_size,font);
            assert_eq!(pseudo.line_height,LineHeight::Pixels(20.0),"font shorthand and all cannot override excluded inline geometry");
            assert_eq!(pseudo.vertical_align,origin.vertical_align);
            assert_eq!(pseudo.writing_mode,origin.writing_mode);
            assert_eq!(pseudo.direction,origin.direction);
        }
    }
    #[test]
    fn specification_selected_style_cache_preserves_real_box_parent_and_bounds_high_node_storage() {
        let source=alloc::format!("<main>{}<section id=contents><span id=leaf></span></section></main>","<div></div>".repeat(20_000));
        let mut document=crate::html::parse(&source,24_000).unwrap();
        let leaf=crate::selector::query_selector(&document,document.root(),"#leaf").unwrap().unwrap();
        let main=crate::selector::query_selector(&document,document.root(),"main").unwrap().unwrap();
        assert!(leaf.index()>20_000);
        let index=StyleIndex::new(parse("main{display:flex;font-size:20px;color:red}main #leaf{width:2em}section{display:contents}").unwrap());
        let mut lineage=Vec::new();let mut current=Some(leaf);
        while let Some(node)=current {if matches!(document.kind(node),Ok(NodeKind::Element{..})){lineage.push(node);}current=document.composed_parent(node).unwrap();}
        lineage.reverse();
        let mut selected=StyleCache::selected(&lineage).unwrap();let mut dense=StyleCache::default();
        let mut selected_parent=None;let mut dense_parent=None;
        for &node in &lineage {
            let sparse=compute_node_cached(&document,node,selected_parent.as_ref(),&index,&mut selected).unwrap();
            let ordinary=compute_node_cached(&document,node,dense_parent.as_ref(),&index,&mut dense).unwrap();
            assert_eq!(sparse,ordinary);selected_parent=Some(sparse);dense_parent=Some(ordinary);
        }
        let style=selected.node_style(leaf).unwrap();
        assert_eq!(style.width,Some(40.0));assert_eq!(style.display,Display::Block);
        assert_eq!(selected.nodes.capacity(),0);assert_eq!(selected.blooms.capacity(),0);
        assert_eq!(selected.selected.as_ref().unwrap().entries.len(),lineage.len());
        assert_eq!(selected.stats().styled_nodes,lineage.len());
        selected.clear();assert!(selected.selected.is_some());
        document.set_attribute(main,"style","font-size:30px").unwrap();
        let mut parent=None;
        for &node in &lineage {parent=Some(compute_node_cached(&document,node,parent.as_ref(),&index,&mut selected).unwrap());}
        assert_eq!(selected.node_style(leaf).unwrap().width,Some(60.0));
        assert_eq!(selected.nodes.capacity(),0);assert_eq!(selected.blooms.capacity(),0);
    }

    #[test]
    fn specification_animation_context_endpoints_use_actual_font_and_inherited_property_values() {
        let document = crate::html::parse("<div id=parent style='font-size:10px;opacity:0.25'><div id=target style='font-size:10px;margin-left:0;width:20px'></div></div>", 64).unwrap();
        let mut session = crate::session::RenderSession::new(document);
        let parent = crate::selector::query_selector(session.document(), session.document().root(), "#parent").unwrap().unwrap();
        let target = crate::selector::query_selector(session.document(), session.document().root(), "#target").unwrap().unwrap();
        let parent_style = session.computed_style(parent).unwrap();
        let target_style = session.computed_style(target).unwrap();
        let environment = session.media_environment();
        let query = ContainerUnitContext::no_container(environment);
        for (property, authored, expected) in [("margin-left", "10em", "100px"), ("margin-left", "20em", "200px"), ("width", "calc(10em + 5px)", "105px"), ("opacity", "inherit", "0.25")] {
            assert_eq!(target_style.computed_animation_endpoint(session.document(), target, Some(&parent_style), None, property, authored, None, environment, query).unwrap().as_deref(), Some(expected), "{property}:{authored}");
        }
    }

    #[test]
    fn specification_animation_context_admission_keeps_numeric_zero_fast_and_length_zero_computed() {
        assert!(!animation_value_needs_context("opacity","0"));
        assert!(!animation_value_needs_context("flex-grow","0"));
        assert!(!animation_value_needs_context("line-height","0"));
        assert!(animation_value_needs_context("width","0"));
        assert!(animation_value_needs_context("margin-left","0"));
        assert!(animation_value_needs_context("width","calc(1em + 2px)"));
        assert!(animation_value_needs_context("width","round(1em, 2px)"));
        assert!(animation_value_needs_context("opacity","sin(1em)"));
        assert!(!supports_property_value("width","round(1em, 2px)"));
        assert!(!supports_property_value("opacity","sin(1em)"));
    }

