#[cfg(test)]
mod registered_animation_snapshot_guards {
    use super::*;
    #[test]
    fn specification_registered_animation_snapshot_shared_registry_csswide_and_math() {
        let document=crate::html::parse("<style>@property --length {syntax:'<length>';inherits:false;initial-value:0px}@property --inherited {syntax:'<length>';inherits:true;initial-value:10000px}@property --other {syntax:'<length>';inherits:false;initial-value:1px}</style><div id=parent style='--length:9px;--inherited:0px;font-size:10px'><div id=target style='--length:20px;--other:7px;font-size:10px'></div></div>",128).unwrap();
        let mut session=crate::session::RenderSession::new(document);
        let parent=crate::selector::query_selector(session.document(),session.document().root(),"#parent").unwrap().unwrap();
        let target=crate::selector::query_selector(session.document(),session.document().root(),"#target").unwrap().unwrap();
        let parent_style=session.computed_style(parent).unwrap();let style=session.computed_style(target).unwrap();
        let registrations=session.registered_custom_property_snapshot().unwrap();
        let viewport=session.media_environment();let query=ContainerUnitContext::no_container(viewport);
        for (property,value,expected) in [("--length","revert","0px"),("--inherited","revert","0px"),("--length","initial","0px"),("--length","inherit","9px"),("--length","10em","100px"),("--length","calc(2em + 5px)","25px"),("--length","var(--other)","7px")] {
            assert_eq!(style.computed_animation_endpoint_with_registrations(session.document(),target,Some(&parent_style),None,property,value,None,viewport,query,Some(registrations.clone())).unwrap().as_deref(),Some(expected),"{property}:{value}");
        }
        let mut eligibility=EffectEligibility::all();eligibility.registrations=Some(registrations.clone());
        let mut replay=style.clone();replay.apply_animation_snapshot(session.document(),target,Some(&parent_style),None,None,viewport,&[("--length".into(),"3em".into())],&eligibility).unwrap();
        assert_eq!(replay.custom_properties().iter().find(|(name,_)|name=="--length").and_then(|(_,value)|value.as_deref()),Some("30px"));
        assert_eq!(replay.custom_properties().iter().find(|(name,_)|name=="--other").and_then(|(_,value)|value.as_deref()),Some("7px"));
        assert!(Arc::ptr_eq(eligibility.registrations.as_ref().unwrap(),&registrations));
        assert!(eligibility.checked_retained_bytes().is_some());
    }
}

/// Individual transform endpoints share ordinary computed owner context while
/// translation percentages stay unresolved until rendering.
pub fn combine_animation_individual_transform(property:&str,from:&str,to:&str,operation:registered_properties::ComputedValueOperation,style:&Style,viewport:MediaEnvironment,text:Option<&dyn TextShaper>,query:ContainerUnitContext)->Option<String>{
    let slot=match property{"translate"=>239,"rotate"=>240,"scale"=>241,_=>return None};
    individual_transforms::combine(slot,from,to,operation,style_length_context(text,style,viewport,None),query)
}
